INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU', 'kiswahili', 9, 'Sikiliza na uchangie mjadala ipasavyo', ARRAY['KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.a', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.b', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.c']::text[], 'Names the features to keep in this kind of talk (mjadala), picks the better of two ways to listen or reply in a situation on kupiga marufuku mifuko ya plastiki, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Dondoa habari mahususi katika kifungu cha simulizi', ARRAY['KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Panga matukio yanavyofuatana katika kifungu', ARRAY['KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Fanya utabiri na ufasiri kutokana na kifungu', ARRAY['KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Eleza maana ya msamiati kama ulivyotumiwa katika kifungu', ARRAY['KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.d']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI', 'KISW.G9.KUANDI.T1_VIAKIFISHI', 'kiswahili', 9, 'Tumia koloni na semi koloni', ARRAY['KISW.G9.KUANDI.T1_VIAKIFISHI.a', 'KISW.G9.KUANDI.T1_VIAKIFISHI.b', 'KISW.G9.KUANDI.T1_VIAKIFISHI.c']::text[], 'Mtoto hutumia koloni (:) kuleta orodha au maelezo, na semi koloni (;) kutenganisha sentensi zinazohusiana. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI', 'KISW.G9.SARUFI.T1_VIHUSISHI', 'kiswahili', 9, 'Tambua vihusishi vya mahali na vya wakati', ARRAY['KISW.G9.SARUFI.T1_VIHUSISHI.a', 'KISW.G9.SARUFI.T1_VIHUSISHI.b']::text[], 'Mtoto hutambua vihusishi vya mahali (mbele ya, nyuma ya, juu ya, chini ya, ndani ya) na vya wakati (kabla ya, baada ya, wakati wa) na kuvitumia ipasavyo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA', 'kiswahili', 9, 'Tofautisha sauti /b/ na /mb/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.a', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.b', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.c']::text[], 'Hears, says and writes the right sound in syllables and words with /b/ na /mb/ (bali and mbali, bega and mbega), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA', 'kiswahili', 9, 'Fafanua ujumbe wa matini aliyosoma', ARRAY['KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.a', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.b', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU', 'kiswahili', 9, 'Tambua ujumbe, lugha na muundo wa kujibu barua ya kirafiki', ARRAY['KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.a', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.b', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.c']::text[], 'Mtoto hueleza kuwa jibu la barua hushukuru, hujibu maswali ya mwandishi, hutumia lugha ya kirafiki na hufuata muundo wa barua ya kirafiki. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU', 'kiswahili', 9, 'Jibu barua ya kirafiki kwa ujumbe, lugha na muundo ufaao', ARRAY['KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.d']::text[], 'Tells barua ya kirafiki from other kinds of writing and its parts, and writes a friendly letter with the address, date, greeting, asking after the friend, the news, and a friendly closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU', 'KISW.G9.SARUFI.T2_VIHUSISHI', 'kiswahili', 9, 'Tambua vihusishi vya -a unganifu na vya sababu', ARRAY['KISW.G9.SARUFI.T2_VIHUSISHI.a', 'KISW.G9.SARUFI.T2_VIHUSISHI.b']::text[], 'Mtoto hutambua kihusishi cha -a unganifu (cha, wa, ya: kitabu cha mwalimu) na cha sababu (kwa sababu ya, kwa ajili ya, kutokana na). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI', 'KISW.G9.KUSIKI.T3_SEMI', 'kiswahili', 9, 'Eleza maana, aina na sifa za semi', ARRAY['KISW.G9.KUSIKI.T3_SEMI.a', 'KISW.G9.KUSIKI.T3_SEMI.b', 'KISW.G9.KUSIKI.T3_SEMI.c', 'KISW.G9.KUSIKI.T3_SEMI.d']::text[], 'Explains the maana of semi (tashbihi, sitiari) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Eleza maana na sifa za shairi', ARRAY['KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.a', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.b', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.c']::text[], 'Explains the utanzu of a shairi read in class ("Sauti ya Mama Dunia") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Fafanua ujumbe wa insha ya masimulizi kupitia muundo na wahusika', ARRAY['KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.b', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.c', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.d']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI', 'KISW.G9.SARUFI.T3_VIHUSISHI', 'kiswahili', 9, 'Tambua vihusishi vilinganishi na kihusishi na', ARRAY['KISW.G9.SARUFI.T3_VIHUSISHI.a', 'KISW.G9.SARUFI.T3_VIHUSISHI.b']::text[], 'Mtoto hutambua vihusishi vilinganishi (kuliko, kama, mithili ya) na kihusishi na kinachoonyesha pamoja (pamoja na). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI', 'KISW.G9.KUSIKI.T4_SEMI', 'kiswahili', 9, 'Wasilisha semi kwa kuzingatia vipengele vya uwasilishaji', ARRAY['KISW.G9.KUSIKI.T4_SEMI.a', 'KISW.G9.KUSIKI.T4_SEMI.b', 'KISW.G9.KUSIKI.T4_SEMI.c', 'KISW.G9.KUSIKI.T4_SEMI.d', 'KISW.G9.KUSIKI.T4_SEMI.e']::text[], 'Explains the uwasilishaji of semi (vitendawili, nahau) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA', 'kiswahili', 9, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.a', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.b', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.c', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.d', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Andika insha ya masimulizi kwa lugha ya kitamathali, matendo ya wahusika na mandhari', ARRAY['KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.b', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI', 'kiswahili', 9, 'Tofautisha -ki- ya masharti na -ka- ya kufuatana', ARRAY['KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.a', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.b']::text[], 'Mtoto hutambua -ki- ya masharti (Ukisoma utafaulu) na -ka- ya kufuatana (Alifika akaketi), na hutofautisha kila mmoja. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ', 'kiswahili', 9, 'Sikiliza kwa ufahamu na ujibu maswali', ARRAY['KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.a', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.b', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.c', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.d']::text[], 'Names the features to keep in this kind of talk (ufahamu), picks the better of two ways to listen or reply in a situation on kazi za nyumbani kwa wavulana na wasichana, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Dondoa habari, tabiri na eleza msamiati katika kifungu cha ufahamu', ARRAY['KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU', 'kiswahili', 9, 'Eleza shajara na vipengele vyake', ARRAY['KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.a', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.b']::text[], 'Mtoto hueleza shajara ni kumbukumbu ya kila siku ya matukio na hisia za mwandishi, huandikwa kwa nafsi ya kwanza na huwa na tarehe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU', 'kiswahili', 9, 'Andika shajara kwa kuzingatia vipengele vyake', ARRAY['KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.c']::text[], 'Tells shajara from other kinds of writing and its parts, and writes a dated diary entry of the right kind in the first person; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI', 'kiswahili', 9, 'Tambua hali ya masharti ya -nge- na -ngali-', ARRAY['KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.a', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.b', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.c']::text[], 'Mtoto hueleza hali ya masharti na hutambua -nge- (Angesoma angefaulu) na -ngali- (Angalijua angalikuja) zinazoonyesha sharti lisilotimia. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MSIMAMO', 'KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS', 'kiswahili', 9, 'Eleza msimamo na mielekeo ya ujumbe wa matini ya kusikiliza', ARRAY['KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.b', 'KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.c', 'KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.a']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Eleza maudhui, dhamira na msamiati katika shairi', ARRAY['KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.b', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.c', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.a']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Eleza insha za methali', ARRAY['KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.b']::text[], 'Mtoto hueleza methali ni msemo wenye hekima na kuwa insha ya methali hufafanua maana ya methali kwa kutumia hadithi au mfano. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Andika insha ya methali kwa kuzingatia vipengele vyake', ARRAY['KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA', 'KISW.G9.SARUFI.T6_VIELEZI', 'kiswahili', 9, 'Tambua vielezi vya namna na vya wakati', ARRAY['KISW.G9.SARUFI.T6_VIELEZI.a', 'KISW.G9.SARUFI.T6_VIELEZI.b']::text[], 'Mtoto hutambua vielezi vya namna (polepole, haraka, kwa upole) na vya wakati (jana, leo, kesho, mapema, sasa). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT', 'kiswahili', 9, 'Tathmini ujumbe, mtazamo na msamiati wa mzungumzaji', ARRAY['KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.c', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.d', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.e', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.a', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.b']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T7_.KUFUPISHA', 'KISW.G9.KUSOMA.T7_', 'kiswahili', 9, 'Fupisha kifungu kwa kuzingatia vipengele vya ufupisho', ARRAY['KISW.G9.KUSOMA.T7_.a', 'KISW.G9.KUSOMA.T7_.b', 'KISW.G9.KUSOMA.T7_.c']::text[], 'Explains what a summary is, picks the main points of a passage on the theme (not the examples), and writes them in his own words, in order, within the word limit and without his own opinion; written summaries are marked by the teacher, and in the app the child picks the right point in 8 of 10 new items.', '["chagua hoja kuu","tambua kisichofaa katika ufupisho","andika ufupisho (mwalimu anasahihisha)"]'::jsonb, '["analysis","synthesis"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Tumia lugha inayoathiri hisia katika insha ya maelezo', ARRAY['KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.b', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI', 'KISW.G9.SARUFI.T7_VIELEZI', 'kiswahili', 9, 'Tambua vielezi vya mahali na vya idadi', ARRAY['KISW.G9.SARUFI.T7_VIELEZI.a', 'KISW.G9.SARUFI.T7_VIELEZI.b']::text[], 'Mtoto hutambua vielezi vya mahali (hapa, pale, huku, kule, nyumbani, mjini) na vya idadi (mara mbili, kidogo, sana, mara nyingi). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA', 'kiswahili', 9, 'Zungumza kwa kushawishi', ARRAY['KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.a', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.b', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.c', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.d']::text[], 'Names the features to keep in this kind of talk (kushawishi), picks the better of two ways to listen or reply in a situation on kujiunga na klabu ya amani shuleni, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Eleza mandhari na ploti ya shairi', ARRAY['KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.a', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.b', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.c']::text[], 'Explains the mandhari of a shairi read in class ("Sauti ya Mama Dunia") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Fafanua muundo wa shairi', ARRAY['KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.d', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.e']::text[], 'Explains the muundo of a shairi read in class ("Sauti ya Mama Dunia") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI', 'KISW.G9.KUANDI.T8_VIAKIFISHI', 'kiswahili', 9, 'Tumia mabano na kistari kifupi', ARRAY['KISW.G9.KUANDI.T8_VIAKIFISHI.a', 'KISW.G9.KUANDI.T8_VIAKIFISHI.b']::text[], 'Mtoto hutumia mabano ( ) kuweka maelezo ya ziada na kistari kifupi (-) kati ya tarakimu (kurasa 5-10) au kuvunja neno mwishoni mwa mstari. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_', 'kiswahili', 9, 'Tumia ngeli za U-ZI na YA-YA na upatanisho wa kisarufi', ARRAY['KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.a', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.b', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua nomino za U-ZI (ukuta, kuta; wimbo, nyimbo) zinazotumia u- na zi-, na za YA-YA (maji, mafuta) zinazotumia ya-. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA', 'kiswahili', 9, 'Tofautisha sauti /j/ na /nj/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.a', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.b', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.c']::text[], 'Hears, says and writes the right sound in syllables and words with /j/ na /nj/ (jia and njia, jaa and njaa), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Dondoa habari na eleza maana ya maneno katika kifungu cha kushawishi', ARRAY['KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Andika insha ya masimulizi ukikuza wazo baina ya aya', ARRAY['KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.b', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_', 'kiswahili', 9, 'Tumia ngeli za KU na PA-KU-MU na upatanisho wa kisarufi', ARRAY['KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.a', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.b', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua ngeli ya KU (vitenzi-jina: kusoma kunafurahisha) na ya PA-KU-MU (mahali: hapa pazuri, kule kuzuri, humu mwazuri). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO', 'kiswahili', 9, 'Wasilisha mazungumzo kwa kuzingatia vipengele vya uwasilishaji', ARRAY['KISW.G9.KUSIKI.T10_MAZUNGUMZO.a', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.b', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.c', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.d']::text[], 'Explains the uwasilishaji of mazungumzo (malumbano ya utani, mawaidha) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Chambua wahusika na sifa zao katika shairi', ARRAY['KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.a', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.b', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.c', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.d']::text[], 'Explains the wahusika of a shairi read in class ("Sauti ya Mama Dunia") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 9, 'Tambua vipengele vya barua rasmi ya kuomba kazi', ARRAY['KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.a', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.b']::text[], 'Mtoto hutambua anwani mbili, tarehe, salamu rasmi, kichwa cha barua, utangulizi, sifa za mwombaji, hitimisho na jina, na kuwa lugha ni ya heshima. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 9, 'Andika barua rasmi ya kuomba kazi', ARRAY['KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.c']::text[], 'Tells barua rasmi from other kinds of writing and its parts, and writes an official letter with two addresses, the date, a formal greeting, a KUH: line, the message and Wako mtiifu with a signature; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH', 'kiswahili', 9, 'Tambua vinyume vya vihusishi', ARRAY['KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.a', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.b', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.c']::text[], 'Mtoto hutambua vinyume vya vihusishi (mbele ya na nyuma ya, juu ya na chini ya, ndani ya na nje ya, kabla ya na baada ya). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S', 'kiswahili', 9, 'Zungumza katika muktadha wa sherehe', ARRAY['KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.a', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.b', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.c', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.d', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.e']::text[], 'Names the features to keep in this kind of talk (sherehe), picks the better of two ways to listen or reply in a situation on sherehe ya kuhitimu darasa la tisa, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA', 'kiswahili', 9, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.a', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.b', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.c', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.d']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Andika insha ya maelezo kwa mtazamo mahususi', ARRAY['KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN', 'kiswahili', 9, 'Tambua kauli ya kutendana, kutendeana na kutendesha', ARRAY['KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.a', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.b']::text[], 'Mtoto hutambua kutendana (pigana), kutendeana (pigiana) na kutendesha (somesha), na hutofautisha maana zake. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ', 'kiswahili', 9, 'Eleza habari na msamiati katika matini ya kusikiliza', ARRAY['KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.a', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.b', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.c']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA', 'kiswahili', 9, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.a', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.b', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.c', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.d']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI', 'kiswahili', 9, 'Eleza hotuba ya kushawishi na vipengele vyake', ARRAY['KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.a', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.b']::text[], 'Mtoto hueleza hotuba ya kushawishi hulenga kumfanya msikilizaji akubali wazo au achukue hatua, na hutambua salamu, utangulizi, hoja, mifano, wito na shukrani. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI', 'kiswahili', 9, 'Andika hotuba ya kushawishi kwa kuzingatia vipengele vyake', ARRAY['KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.c']::text[], 'Tells hotuba from other kinds of writing and its parts, and writes a speech with the itifaki, words spoken to the audience, facts the listener can use and a closing with thanks; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI', 'kiswahili', 9, 'Tambua sentensi tata', ARRAY['KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.a', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.b', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.c', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.d']::text[], 'Mtoto hueleza sentensi tata ni yenye maana zaidi ya moja kutokana na muundo wake, kama "Mama alimpiga mtoto na fimbo". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO', 'kiswahili', 9, 'Chambua wahusika katika mazungumzo', ARRAY['KISW.G9.KUSIKI.T13_MAZUNGUMZO.a', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.b', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.c', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.d', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.e', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.f']::text[], 'Explains the wahusika of mazungumzo (mawaidha, malumbano ya utani) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA', 'kiswahili', 9, 'Tambua mbinu za lugha na umuhimu wake katika shairi', ARRAY['KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.a', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.b', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.c', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.d']::text[], 'Explains the mbinu of a shairi read in class ("Sauti ya Mama Dunia") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI', 'kiswahili', 9, 'Andika insha ya maelezo kuhusu hali', ARRAY['KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.a', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.b', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI', 'KISW.G9.SARUFI.T13_UKANUSHAJI', 'kiswahili', 9, 'Kanusha hali ya masharti', ARRAY['KISW.G9.SARUFI.T13_UKANUSHAJI.a', 'KISW.G9.SARUFI.T13_UKANUSHAJI.b']::text[], 'Mtoto hukanusha -nge- kwa -singe- (angekuja, asingekuja), -ngali- kwa -singali- na -ki- kwa -sipo- (akisoma, asiposoma). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO', 'kiswahili', 9, 'Tambua vipengele vya lugha katika mazungumzo', ARRAY['KISW.G9.KUSIKI.T14_MAZUNGUMZO.a', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.b', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.c', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.d']::text[], 'Explains the lugha of mazungumzo (mawaidha, malumbano ya utani) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU', 'kiswahili', 9, 'Soma kifungu cha mjadala: habari, msamiati na mitazamo', ARRAY['KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.a', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.b', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU', 'kiswahili', 9, 'Tambua aina za shajara na uandike shajara', ARRAY['KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.a', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.b', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.c']::text[], 'Tells shajara from other kinds of writing and its parts, and writes a dated diary entry of the right kind in the first person; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N', 'kiswahili', 9, 'Tambua nomino katika hali ya udogo na ukubwa', ARRAY['KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.a', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.b']::text[], 'Mtoto hutambua udogo (kijiji, kijiti, kitoto, kijumba) na ukubwa (jitu, jumba, joka), na hubadilisha nomino ipasavyo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT', 'kiswahili', 9, 'Sikiliza na utathmini mazungumzo', ARRAY['KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.a', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.b', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.c']::text[], 'Names the features to keep in this kind of talk (kutathmini), picks the better of two ways to listen or reply in a situation on mchango wa vijana katika kudumisha amani, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO', 'KISW.G9.KUSOMA.T15_UFUPISHO', 'kiswahili', 9, 'Jadili vipengele vya ufupisho wa habari', ARRAY['KISW.G9.KUSOMA.T15_UFUPISHO.a']::text[], 'Mtoto hujadili kuwa ufupisho huhifadhi habari kuu na mtiririko wake, hutumia maneno ya mfupishaji na haunakili kifungu. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'KISW.G9.KUSOMA.T15_UFUPISHO', 'kiswahili', 9, 'Tambua vipengele vya ufupisho wa habari katika matini', ARRAY['KISW.G9.KUSOMA.T15_UFUPISHO.a', 'KISW.G9.KUSOMA.T15_UFUPISHO.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE', 'kiswahili', 9, 'Jibu baruapepe kwa kuzingatia vipengele vifaavyo', ARRAY['KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.a', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.b']::text[], 'Tells baruapepe from other kinds of writing and its parts, and writes an email with the receiver''s address, a short subject, a greeting, the message in correct Kiswahili and a closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM', 'kiswahili', 9, 'Jadili kanuni za kubadilisha usemi na uzitumie katika matini', ARRAY['KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.a', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.b']::text[], 'States the rules for turning direct speech into reported speech (marks, kwamba/kuwa or kama, person, tense, time and place words, questions and commands) and uses both kinds correctly in a passage, in 8 of 10 new items.', '["chagua kanuni sahihi","badilisha usemi","tambua kosa","andika kifungu"]'::jsonb, '["rule","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
