INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA.M9_ORL_NOREASON_T1', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA', 'States a side with no reason or example.', '{"question":"Katika mjadala kuhusu kupiga marufuku mifuko ya plastiki, ni mchango upi bora?","wrong_answer":"Nakubali.","correct_answer":"Nakubali kwa sababu... kwa mfano..."}'::jsonb, 'The child thinks agreeing is contributing.', 'The question "Katika mjadala kuhusu kupiga marufuku mifuko ya plastiki, ni mchango upi bora?" with "Nakubali." among the options.', 'Point-reason-example frame for every contribution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA.M9_ORL_ATTACK_T1', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA', 'Attacks the speaker, not the point (Wewe hujui chochote).', '{"question":"Hukubaliani na hoja ya mwenzako. Unasemaje?","wrong_answer":"Wewe hujui unachosema!","correct_answer":"Naheshimu hoja yako, lakini..."}'::jsonb, 'Disagreeing feels personal.', 'The question "Hukubaliani na hoja ya mwenzako. Unasemaje?" with "Wewe hujui unachosema!" among the options.', 'Model "Naheshimu..., lakini..."; ban personal words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA.M9_ORL_INTERRUPT_T1', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA.M9_ORL_OFFTOPIC_T1', 'KISW.G9.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MJADALA', 'Answers or speaks on something other than the topic (kupiga marufuku mifuko ya plastiki).', '{"question":"Mada ni kupiga marufuku mifuko ya plastiki. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia kupiga marufuku mifuko ya plastiki kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni kupiga marufuku mifuko ya plastiki. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS9_RS_HABARI_DETAIL', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS9_RS_HABARI_OPPOSITE', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
