INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M9_HAB_RS_HABARI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Answers a "why" question with a "what" (an event, not its reason).', '{"question":"Kwa nini mhusika alikimbia nyumbani?","wrong_answer":"alikimbia nyumbani","correct_answer":"kwa sababu aliogopa mbwa wa jirani"}'::jsonb, 'The child finds the sentence with the words of the question and copies the event.', 'The question "Kwa nini mhusika alikimbia nyumbani?" with "alikimbia nyumbani" among the options.', 'Underline the question word: nini, nani, wapi, lini, kwa nini; the answer must fit it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO.M9_MAT_RS_MATUKIO', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'Orders the events as they are told in the question or the options, not as they happen in the passage.', '{"question":"Ni tukio lipi lilitokea kwanza katika kifungu?","wrong_answer":"tukio lililotajwa kwanza katika swali","correct_answer":"tukio la kwanza katika kifungu"}'::jsonb, 'The order of the options is taken for the order of the story.', 'The question "Ni tukio lipi lilitokea kwanza katika kifungu?" with "tukio lililotajwa kwanza katika swali" among the options.', 'Number the events in the margin of the passage before looking at the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI.M9_UTB_RS_UTABIRI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'Predicts with no clue from the passage, from what he wishes would happen.', '{"question":"Kutokana na kifungu, nini kitatokea baadaye?","wrong_answer":"mhusika atakuwa tajiri sana","correct_answer":"jibu linalotokana na vidokezo vya kifungu"}'::jsonb, 'Prediction is taken as imagination.', 'The question "Kutokana na kifungu, nini kitatokea baadaye?" with "mhusika atakuwa tajiri sana" among the options.', 'Every prediction needs a clue: "kwa sababu kifungu kinasema..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI.M9_MSM_RS_MSAMIATI', 'KISW.G9.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'Gives the meaning of a look-alike word, or the everyday meaning where the passage means another.', '{"question":"Katika kifungu, neno \"kupiga\" katika \"alipiga simu\" lina maana gani?","wrong_answer":"kumpiga mtu","correct_answer":"kuwasiliana kwa simu"}'::jsonb, 'The child knows one meaning and does not test it against the sentence.', 'The question "Katika kifungu, neno "kupiga" katika "alipiga simu" lina maana gani?" with "kumpiga mtu" among the options.', 'Put each meaning into the sentence; keep the one that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI.M_KS9_KO_KOLONI', 'KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI', 'Uses a semi-colon before a list.', '{"question":"Ni alama ipi huleta orodha?","wrong_answer":"semi koloni","correct_answer":"koloni"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "semi koloni" next to the right answer and ask the question again in a new sentence.', 'Koloni huleta orodha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI.M_KS9_KO_SEMI', 'KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI', 'Uses a colon between two related sentences.', '{"question":"Ni alama ipi hutenganisha sentensi mbili zinazohusiana?","wrong_answer":"koloni","correct_answer":"semi koloni"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "koloni" next to the right answer and ask the question again in a new sentence.', 'Semi koloni hutenganisha sentensi zinazohusiana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI.M_KS9_KO_MFANO', 'KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI', 'Wrong example.', '{"question":"Ni sentensi ipi imetumia koloni sawa?","wrong_answer":"Nilinunua: mkate maziwa sukari.","correct_answer":"Nilinunua vitu hivi: mkate, maziwa na sukari."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Nilinunua: mkate maziwa sukari." next to the right answer and ask the question again in a new sentence.', 'Koloni hufuata maelezo kisha orodha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI.M9_KOL_SEMI_COMMA', 'KISW.G9.KUANDI.T1_VIAKIFISHI.KOLONI', 'Uses a comma where two full sentences on one idea are joined (semi koloni), or a semi koloni before a list (koloni).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Tulifika mapema, walimu walikuwa bado hawajafika.","correct_answer":"Tulifika mapema; walimu walikuwa bado hawajafika."}'::jsonb, 'The comma is the only joining mark the child uses.', 'The question "Ni ipi imeandikwa sawa?" with "Tulifika mapema, walimu walikuwa bado hawajafika." among the options.', 'Koloni (:) introduces a list or an explanation; semi koloni (;) joins two complete, linked sentences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI.M_KS9_VM_MAHALI', 'KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI', 'Gives a time word for a place.', '{"question":"Ni kihusishi kipi cha mahali?","wrong_answer":"baada ya","correct_answer":"mbele ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "baada ya" next to the right answer and ask the question again in a new sentence.', 'Mbele ya ni kihusishi cha mahali.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI.M_KS9_VM_WAKATI', 'KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI', 'Gives a place word for a time.', '{"question":"Ni kihusishi kipi cha wakati?","wrong_answer":"karibu na","correct_answer":"kabla ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "karibu na" next to the right answer and ask the question again in a new sentence.', 'Kabla ya ni kihusishi cha wakati.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI.M_KS9_VM_SENTENSI', 'KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI', 'Does not use "ya" after the preposition.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Kitabu kiko juu meza.","correct_answer":"Kitabu kiko juu ya meza."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Kitabu kiko juu meza." next to the right answer and ask the question again in a new sentence.', 'Vihusishi vingi hufuatwa na ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI.M9_VH_TIME_PLACE', 'KISW.G9.SARUFI.T1_VIHUSISHI.VIH_MAHALI', 'Uses a place relating word for time (ndani ya saa mbili is right; the child writes juu ya saa mbili for "after two hours").', '{"question":"Jaza: Tutamaliza ___ saa mbili.","wrong_answer":"juu ya","correct_answer":"baada ya"}'::jsonb, 'English "over two hours" and place words feel interchangeable.', 'The question "Jaza: Tutamaliza ___ saa mbili." with "juu ya" among the options.', 'Sort relating words into place (juu ya, chini ya, ndani ya) and time (kabla ya, baada ya, tangu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SWAP_T2', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /mb/ for /b/, so bali (but) becomes mbali (far).', '{"question":"Mwalimu anasema: \"bali\". Umesikia neno lipi?","wrong_answer":"mbali","correct_answer":"bali"}'::jsonb, 'The nasal (n- or m-) before b is soft and quick; a child who does not hear it writes and says the word without it, or adds it where it does not belong, and the meaning changes.', 'The question "Mwalimu anasema: "bali". Umesikia neno lipi?" with "mbali" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SPELL_T2', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (mbega where bega is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"a shoulder\".","wrong_answer":"mbega","correct_answer":"bega"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "a shoulder"." with "mbega" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SAME_T2', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"bega\" na \"mbega\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""bega" na "mbega" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_TWISTER_T2', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Mazoezi ya asubuhi huimarisha mwili.","correct_answer":"Mbega mbele ya mbuzi alibeba mbegu mbili mbichi mbugani."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Mazoezi ya asubuhi huimarisha mwili." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SYLL_T2', 'KISW.G9.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Splits the syllable with the nasal wrongly (m-bali instead of keeping the nasal with its consonant).', '{"question":"Neno \"mbali\" lina silabi zipi?","wrong_answer":"m-bali","correct_answer":"mba-li"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "mbali" lina silabi zipi?" with "m-bali" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS9_RS_UJUMBE_DETAIL', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS9_RS_UJUMBE_OPPOSITE', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M_KS9_RS_UJUMBE_NOTSAID', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE.M9_UJM_RS_UJUMBE', 'KISW.G9.KUSOMA.T2_KUSOMA_KWA_MAPANA.RS_UJUMBE', 'Gives a detail of the chosen text as its message.', '{"question":"Ujumbe wa matini uliyochagua ni upi?","wrong_answer":"jambo moja dogo lililotokea","correct_answer":"funzo kuu la matini yote"}'::jsonb, 'The detail is vivid.', 'The question "Ujumbe wa matini uliyochagua ni upi?" with "jambo moja dogo lililotokea" among the options.', 'Ask what the whole text teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA.M_KS9_JB_SHUKRANI', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA', 'Starts a reply with a complaint.', '{"question":"Jibu la barua huanza kwa nini?","wrong_answer":"malalamiko","correct_answer":"shukrani kwa barua uliyopokea"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "malalamiko" next to the right answer and ask the question again in a new sentence.', 'Jibu huanza kwa shukrani.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA.M_KS9_JB_MASWALI', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA', 'Ignores the questions.', '{"question":"Jibu la barua hufanya nini kuhusu maswali?","wrong_answer":"huyapuuza","correct_answer":"huyajibu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "huyapuuza" next to the right answer and ask the question again in a new sentence.', 'Jibu hujibu maswali ya mwandishi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA.M_KS9_JB_LUGHA', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA', 'Uses a formal register.', '{"question":"Lugha ya kujibu barua ya kirafiki ni ipi?","wrong_answer":"ya kiofisi kali","correct_answer":"ya kirafiki na heshima"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya kiofisi kali" next to the right answer and ask the question again in a new sentence.', 'Lugha ni ya kirafiki na heshima.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA.M9_INS_FORMAL_T2', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA', 'Writes to a friend in the stiff words of an official letter (Mheshimiwa, Kuhusu:, Wako mtiifu).', '{"question":"Ni salamu ipi inafaa katika barua kwa rafiki?","wrong_answer":"Mheshimiwa Bwana,","correct_answer":"Mpendwa rafiki yangu Amina,"}'::jsonb, 'The child has seen official letters at school and thinks every letter is written that way.', 'The question "Ni salamu ipi inafaa katika barua kwa rafiki?" with "Mheshimiwa Bwana," among the options.', 'Put a friendly and an official letter side by side; the child highlights the words that differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA.M9_INS_NOASK_T2', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA', 'Starts with the news straight after the greeting, with no asking after the friend (maulizo ya hali).', '{"question":"Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?","wrong_answer":"Nataka kukueleza kuhusu safari yetu.","correct_answer":"Hujambo? Natumai u buheri wa afya."}'::jsonb, 'The child goes to what he wants to say, as in a text message.', 'The question "Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?" with "Nataka kukueleza kuhusu safari yetu." among the options.', 'Order the parts on cards: anwani, tarehe, salamu, maulizo ya hali, ujumbe, hitimisho, jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA.M9_INS_DATE_T2', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA', 'Leaves out the date or writes it in the middle of the letter.', '{"question":"Tarehe huandikwa wapi katika barua ya kirafiki?","wrong_answer":"mwishoni, baada ya jina","correct_answer":"chini ya anwani ya mwandishi, upande wa kulia juu"}'::jsonb, 'The date is not part of what the child wants to say, so he forgets it.', 'The question "Tarehe huandikwa wapi katika barua ya kirafiki?" with "mwishoni, baada ya jina" among the options.', 'Label a model letter; the child places a date card on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA.M9_INS_SIGN_T2', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.KUJIBU_BARUA', 'Ends with "Wako mtiifu" and a full name and title, as in an official letter.', '{"question":"Ni hitimisho lipi linafaa katika barua kwa rafiki?","wrong_answer":"Wako mtiifu, Bw. Juma Hamisi","correct_answer":"Ni mimi rafiki yako, Juma"}'::jsonb, 'Again the official model is the only one the child has copied.', 'The question "Ni hitimisho lipi linafaa katika barua kwa rafiki?" with "Wako mtiifu, Bw. Juma Hamisi" among the options.', 'Collect three friendly closings and keep them in the exercise book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA.M9_JB_IGNORE', 'KISW.G9.KUANDI.T2_INSHA_ZA_KIUAMILIFU.JIBU_BARUA', 'Writes his own news and does not answer the questions or the points in the letter received.', '{"question":"Rafiki aliuliza kuhusu mazoezi unayofanya. Jibu lako lianze vipi baada ya salamu?","wrong_answer":"Nataka kukueleza kuhusu sherehe yetu.","correct_answer":"Asante kwa barua yako. Umeuliza kuhusu mazoezi yangu; ninakimbia kila asubuhi..."}'::jsonb, 'The child treats the reply as a new letter.', 'The question "Rafiki aliuliza kuhusu mazoezi unayofanya. Jibu lako lianze vipi baada ya salamu?" with "Nataka kukueleza kuhusu sherehe yetu." among the options.', 'List the questions in the letter received; tick each as you answer it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU.M_KS9_VS_UNGANIFU', 'KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU', 'Mixes the -a unganifu with the cause word.', '{"question":"Ni kihusishi kipi cha -a unganifu?","wrong_answer":"kwa sababu ya","correct_answer":"cha"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kwa sababu ya" next to the right answer and ask the question again in a new sentence.', 'Cha ni kihusishi cha -a unganifu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU.M_KS9_VS_SABABU', 'KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU', 'Mixes the cause word with the -a unganifu.', '{"question":"Ni kihusishi kipi cha sababu?","wrong_answer":"cha","correct_answer":"kwa sababu ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "cha" next to the right answer and ask the question again in a new sentence.', 'Kwa sababu ya ni kihusishi cha sababu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU.M_KS9_VS_UPATANISHO', 'KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU', 'Wrong agreement of -a unganifu.', '{"question":"Kamilisha: kitabu ___ mwalimu.","wrong_answer":"wa","correct_answer":"cha"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wa" next to the right answer and ask the question again in a new sentence.', 'Kitabu hupatana na cha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU.M9_VH_A_CLASS', 'KISW.G9.SARUFI.T2_VIHUSISHI.VIH_SABABU', 'Uses the -a of agreement of another class (Mazoezi ya mwili ni muhimu is right; the child writes mazoezi wa mwili, viungo ya mwili).', '{"question":"Jaza: viungo ___ mwili","wrong_answer":"ya","correct_answer":"vya"}'::jsonb, 'Ya is the commonest form and the child uses it everywhere.', 'The question "Jaza: viungo ___ mwili" with "ya" among the options.', 'Find the first noun and its class: viungo (KI-VI) -> vya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI.M9_FSI_KIND_T3', 'KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI', 'Mixes the two kinds (tashbihi and sitiari) and their purposes.', '{"question":"\"Mkulima huyu ni simba wa shamba\" ni semi ya aina gani?","wrong_answer":"sitiari","correct_answer":"tashbihi"}'::jsonb, 'Both are semi; the child has not fixed what each is for and when it is used.', 'The question ""Mkulima huyu ni simba wa shamba" ni semi ya aina gani?" with "sitiari" among the options.', 'List for each kind: who uses it, when, and why; sort examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI.M9_FSI_WRITTEN_T3', 'KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI', 'Calls semi written literature because it is found in a textbook.', '{"question":"Semi ni utanzu wa fasihi ipi?","wrong_answer":"fasihi andishi","correct_answer":"fasihi simulizi"}'::jsonb, 'The child meets it on the page in class.', 'The question "Semi ni utanzu wa fasihi ipi?" with "fasihi andishi" among the options.', 'Ask: who first made it, and how was it passed on? By mouth, from one generation to the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI.M9_FSI_OCCASION_T3', 'KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI', 'Places the semi in the wrong occasion (a lullaby at a work party, a work song at a funeral).', '{"question":"Tashbihi hutumika lini?","wrong_answer":"wakati wowote","correct_answer":"kusifu au kukosoa tabia katika mazungumzo na hadithi"}'::jsonb, 'The occasion is not stated in the text, and the child does not link form to use.', 'The question "Tashbihi hutumika lini?" with "wakati wowote" among the options.', 'Act out the occasion; which kind fits it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI.M9_FSI_MESSAGE_T3', 'KISW.G9.KUSIKI.T3_SEMI.SEMI_TASHBIHI', 'Gives a line of the text as its message instead of the lesson.', '{"question":"Ujumbe wa \"Mkulima huyu ni simba wa shamba\" ni upi?","wrong_answer":"Mkulima huyu ni simba wa shamba","correct_answer":"mkulima ana nguvu na ujasiri mkubwa kazini."}'::jsonb, 'Copying a line feels like a safe answer.', 'The question "Ujumbe wa "Mkulima huyu ni simba wa shamba" ni upi?" with "Mkulima huyu ni simba wa shamba" among the options.', 'Close the text; say the lesson in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU.M9_FAS_GENRE_T3', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU', 'Takes a shairi for another kind of text (wimbo) or gives the features of the other kind.', '{"question":"Ni sifa ipi ni ya shairi?","wrong_answer":"huandikwa kwa aya ndefu bila mpangilio","correct_answer":"huwa na beti, mishororo, vina na mizani"}'::jsonb, 'The child has met several kinds of literature and keeps one list of features for all of them.', 'The question "Ni sifa ipi ni ya shairi?" with "huandikwa kwa aya ndefu bila mpangilio" among the options.', 'Lay a shairi and a wimbo side by side and list what only the shairi has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU.M9_FAS_ORAL_T3', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU', 'Calls a shairi oral literature (fasihi simulizi) because it can be read aloud or acted.', '{"question":"Shairi ni utanzu wa fasihi ipi?","wrong_answer":"fasihi simulizi","correct_answer":"fasihi andishi"}'::jsonb, 'Plays are acted and poems are recited, so the child thinks of them as spoken.', 'The question "Shairi ni utanzu wa fasihi ipi?" with "fasihi simulizi" among the options.', 'Ask: was it first composed in writing by a known author? Then it is fasihi andishi, even when performed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU.M9_FAS_ONEFEATURE_T3', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU', 'Gives one feature only (length, or rhyme) as the whole meaning of a shairi.', '{"question":"Eleza maana ya shairi.","wrong_answer":"ni maneno yenye vina","correct_answer":"ni utungo wa kisanaa wenye mpangilio wa beti, mishororo, vina na mizani unaowasilisha ujumbe"}'::jsonb, 'The child remembers the most visible feature.', 'The question "Eleza maana ya shairi." with "ni maneno yenye vina" among the options.', 'Build the definition from three parts: what kind of text, its form, its purpose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU.M9_FAS_AUTHOR_T3', 'KISW.G9.KUSOMA.T3_KUSOMA_KWA_KINA.SHAIRI_UTANZU', 'Takes the narrator or a character for the author of the shairi.', '{"question":"Ni nani mwandishi wa \"Sauti ya Mama Dunia\"?","wrong_answer":"Mama Dunia (nafsineni)","correct_answer":"mtunzi aliyetajwa jaladani"}'::jsonb, 'The narrator speaks as "I" and the child takes that voice for the writer.', 'The question "Ni nani mwandishi wa "Sauti ya Mama Dunia"?" with "Mama Dunia (nafsineni)" among the options.', 'Find the author''s name on the cover; the narrator and characters are inside the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE.M9_INS_PARAS_T3', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Mbwa Aliyeokoa Familia\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Mbwa Aliyeokoa Familia" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE.M9_INS_WAHUSIKA_T3', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE', 'Gives the characters no names, no features and no words of their own, so the reader cannot see them.', '{"question":"Ni sentensi ipi inamjenga mhusika vizuri katika insha \"Mbwa Aliyeokoa Familia\"?","wrong_answer":"Mtu mmoja alikuja.","correct_answer":"Mzee Juma, mwenye ndevu nyeupe na fimbo ya mpingo, alisimama mlangoni."}'::jsonb, 'The child thinks of the events, not the people in them.', 'The question "Ni sentensi ipi inamjenga mhusika vizuri katika insha "Mbwa Aliyeokoa Familia"?" with "Mtu mmoja alikuja." among the options.', 'For each character: a name, one look, one trait shown by an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE.M9_INS_END_T3', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Mbwa Aliyeokoa Familia\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza mengi kuhusu jambo hili."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Mbwa Aliyeokoa Familia"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE.M9_INS_OFFTOPIC_T3', 'KISW.G9.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_UJUMBE', 'Puts in points that are not about the title.', '{"question":"Katika insha ya kubuni yenye anwani \"Mbwa Aliyeokoa Familia\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Mbwa Simba, mwenye macho ya kahawia, alisimama mlangoni akibweka bila kukoma."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya kubuni yenye anwani "Mbwa Aliyeokoa Familia", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI.M_KS9_VL_KULIKO', 'KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI', 'Does not know kuliko.', '{"question":"Ni kihusishi kipi kinalinganisha?","wrong_answer":"pamoja na","correct_answer":"kuliko"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pamoja na" next to the right answer and ask the question again in a new sentence.', 'Kuliko hulinganisha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI.M_KS9_VL_NA', 'KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI', 'Does not know na as togetherness.', '{"question":"Katika \"Alikuja na rafiki yake\", na inaonyesha nini?","wrong_answer":"ulinganisho","correct_answer":"pamoja"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ulinganisho" next to the right answer and ask the question again in a new sentence.', 'Na hapa inaonyesha pamoja.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI.M_KS9_VL_KAMA', 'KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI', 'Mixes kama with sababu.', '{"question":"Ni kihusishi kipi kinalinganisha vitu viwili?","wrong_answer":"kwa ajili ya","correct_answer":"kama"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kwa ajili ya" next to the right answer and ask the question again in a new sentence.', 'Kama hulinganisha vitu viwili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI.M9_VH_KULIKO_ZAIDI', 'KISW.G9.SARUFI.T3_VIHUSISHI.VIH_LINGANISHI', 'Uses "zaidi ya" and "kuliko" together (mkubwa zaidi kuliko zaidi ya), or "kama" for comparing degrees.', '{"question":"Jaza: Tembo ni mkubwa ___ kiboko.","wrong_answer":"kama","correct_answer":"kuliko"}'::jsonb, 'English "than" and "as" are mixed.', 'The question "Jaza: Tembo ni mkubwa ___ kiboko." with "kama" among the options.', 'Kuliko / zaidi ya for more; kama / sawa na for equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI.M9_FSI_FORMULA_T4', 'KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI', 'Starts or ends without the opening or closing formula (Kitendawili!).', '{"question":"Msimulizi anaanzaje?","wrong_answer":"anaanza moja kwa moja na kisa","correct_answer":"\"Kitendawili!\" na hadhira hujibu \"Tega!\""}'::jsonb, 'Telling has been practised as reading a text aloud.', 'The question "Msimulizi anaanzaje?" with "anaanza moja kwa moja na kisa" among the options.', 'Practise the formula with the class answering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI.M9_FSI_FLAT_T4', 'KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI', 'Presents in one flat voice, with no change for characters or feelings.', '{"question":"Unapowasilisha, sauti yako iweje?","wrong_answer":"moja tangu mwanzo hadi mwisho","correct_answer":"ibadilike kulingana na mhusika na hisia"}'::jsonb, 'The child is shy and keeps the voice safe.', 'The question "Unapowasilisha, sauti yako iweje?" with "moja tangu mwanzo hadi mwisho" among the options.', 'Give each character a voice; rehearse one line in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI.M9_FSI_GESTURE_T4', 'KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI', 'Uses no gestures, or gestures that do not match the words.', '{"question":"Ni ishara ipi inafaa unapotaja \"mlima mrefu\"?","wrong_answer":"kushika kichwa","correct_answer":"kuinua mkono juu juu"}'::jsonb, 'The body is forgotten under the stress of remembering words.', 'The question "Ni ishara ipi inafaa unapotaja "mlima mrefu"?" with "kushika kichwa" among the options.', 'Mirror pairs: one says, one shows; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI.M9_FSI_NOAUDIENCE_T4', 'KISW.G9.KUSIKI.T4_SEMI.SEMI_VITENDAWILI', 'Presents to the floor or the teacher only, with no eye contact and no call for responses.', '{"question":"Unawasilisha mbele ya darasa. Unawaangalia nani?","wrong_answer":"chini au mwalimu peke yake","correct_answer":"hadhira yote, ukiwashirikisha"}'::jsonb, 'Reciting for marks is done to the teacher.', 'The question "Unawasilisha mbele ya darasa. Unawaangalia nani?" with "chini au mwalimu peke yake" among the options.', 'Divide the room into three; look at each part in turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_WORDBYWORD_T4', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Jamii ilikubaliana kulinda chemchemi ya maji kwa kupanda miti kando yake.\"?","wrong_answer":"Jamii ... ilikubaliana ... kulinda ... chemchemi ... ya ... maji ... kwa ... kupanda ... miti ... kando ... yake.","correct_answer":"Jamii ilikubaliana kulinda chemchemi ya maji kwa kupanda miti kando yake."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Jamii ilikubaliana kulinda chemchemi ya maji kwa kupanda miti kando yake."?" with "Jamii ... ilikubaliana ... kulinda ... chemchemi ... ya ... maji ... kwa ... kupanda ... miti ... kando ... yake." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_RACE_T4', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_FLAT_T4', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, vizazi vijavyo vitapata maji safi?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, vizazi vijavyo vitapata maji safi?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_NOPAUSE_T4', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Ole wetu tusipotunza misitu!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Ole wetu tusipotunza misitu!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_SOUND_T4', 'KISW.G9.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (kulinda read as kurinda).', '{"question":"Neno \"kulinda\" linatamkwa vipi?","wrong_answer":"kurinda","correct_answer":"kulinda"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "kulinda" linatamkwa vipi?" with "kurinda" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI.M9_INS_LUGHA_T4', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Chemchemi Iliyokauka\"?","wrong_answer":"Chemchemi ilikauka.","correct_answer":"Chemchemi iliyokuwa ikicheka kwa sauti ya maji sasa ilinyamaza kama kaburi."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Chemchemi Iliyokauka"?" with "Chemchemi ilikauka." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI.M9_INS_WAHUSIKA_T4', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI', 'Gives the characters no names, no features and no words of their own, so the reader cannot see them.', '{"question":"Ni sentensi ipi inamjenga mhusika vizuri katika insha \"Chemchemi Iliyokauka\"?","wrong_answer":"Mtu mmoja alikuja.","correct_answer":"Mzee Juma, mwenye ndevu nyeupe na fimbo ya mpingo, alisimama mlangoni."}'::jsonb, 'The child thinks of the events, not the people in them.', 'The question "Ni sentensi ipi inamjenga mhusika vizuri katika insha "Chemchemi Iliyokauka"?" with "Mtu mmoja alikuja." among the options.', 'For each character: a name, one look, one trait shown by an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI.M9_INS_MANDHARI_T4', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI', 'Gives no setting (time and place) or one that does not fit the events.', '{"question":"Ni mwanzo upi unaonyesha mandhari ya insha \"Chemchemi Iliyokauka\"?","wrong_answer":"Kisa hiki kilitokea.","correct_answer":"Ilikuwa jioni ya Ijumaa katika soko la Gikomba, watu wakiwa wamesongamana."}'::jsonb, 'The child starts with the action.', 'The question "Ni mwanzo upi unaonyesha mandhari ya insha "Chemchemi Iliyokauka"?" with "Kisa hiki kilitokea." among the options.', 'Answer lini? wapi? hali gani? in the first paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI.M9_INS_HISIA_T4', 'KISW.G9.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_TAMATHALI', 'States feelings with one word (nilihuzunika) and never shows them, so the reader feels nothing.', '{"question":"Ni sentensi ipi inamgusa msomaji zaidi?","wrong_answer":"Nilihuzunika.","correct_answer":"Machozi yalinitiririka nilipoona kibanda chetu kikiteketea."}'::jsonb, 'Showing a feeling needs words for the body and the scene.', 'The question "Ni sentensi ipi inamgusa msomaji zaidi?" with "Nilihuzunika." among the options.', 'Turn "nilihuzunika" into what the body did and what was seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA.M_KS9_KK_KI', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA', 'Takes -ki- as sequence.', '{"question":"Katika \"Ukisoma utafaulu\", -ki- inaonyesha nini?","wrong_answer":"kufuatana","correct_answer":"sharti"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kufuatana" next to the right answer and ask the question again in a new sentence.', '-ki- hapa inaonyesha sharti.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA.M_KS9_KK_KA', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA', 'Takes -ka- as condition.', '{"question":"Katika \"Alifika akaketi\", -ka- inaonyesha nini?","wrong_answer":"sharti","correct_answer":"kufuatana"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "sharti" next to the right answer and ask the question again in a new sentence.', '-ka- inaonyesha tendo linalofuata.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA.M_KS9_KK_MATUMIZI', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA', 'Uses -ki- where -ka- is needed.', '{"question":"Kamilisha: Aliamka ___oga.","wrong_answer":"akioga","correct_answer":"akaoga"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "akioga" next to the right answer and ask the question again in a new sentence.', 'Tendo linalofuata hutumia -ka-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA.M9_KK_KA_NEW_SUBJECT', 'KISW.G9.SARUFI.T4_NYAKATI_NA_HALI.KI_KA', 'Uses -ka- for an action by a different subject that does not follow from the first (Alifika nikaondoka for an unrelated event), or repeats -li- in a chain of actions.', '{"question":"Jaza: Aliamka, ___ (oga), kisha ___ (vaa).","wrong_answer":"alioga, alivaa","correct_answer":"akaoga, akavaa"}'::jsonb, 'The child repeats -li- in every verb of a story.', 'The question "Jaza: Aliamka, ___ (oga), kisha ___ (vaa)." with "alioga, alivaa" among the options.', 'In a chain of past actions, the first verb takes -li- and the following ones -ka-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M9_ORL_NOTNOTE_T5', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Tries to remember everything instead of noting the key points while listening.', '{"question":"Unasikiliza habari ndefu. Ufanye nini?","wrong_answer":"jaribu kukumbuka kila neno","correct_answer":"andika maneno muhimu unaposikiliza"}'::jsonb, 'Listening has been practised for short texts only.', 'The question "Unasikiliza habari ndefu. Ufanye nini?" with "jaribu kukumbuka kila neno" among the options.', 'Practise noting three key words while listening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M9_ORL_ANSWEROUT_T5', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Answers from what he knows, not from what he heard.', '{"question":"Kwa mujibu wa ulichosikiliza kuhusu kazi za nyumbani kwa wavulana na wasichana, ni lipi jibu?","wrong_answer":"jibu la jumla analolijua","correct_answer":"jibu lililotajwa katika kifungu"}'::jsonb, 'The topic is familiar.', 'The question "Kwa mujibu wa ulichosikiliza kuhusu kazi za nyumbani kwa wavulana na wasichana, ni lipi jibu?" with "jibu la jumla analolijua" among the options.', 'Ask: did the speaker say that?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M9_ORL_INTERRUPT_T5', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M9_ORL_OFFTOPIC_T5', 'KISW.G9.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Answers or speaks on something other than the topic (kazi za nyumbani kwa wavulana na wasichana).', '{"question":"Mada ni kazi za nyumbani kwa wavulana na wasichana. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia kazi za nyumbani kwa wavulana na wasichana kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni kazi za nyumbani kwa wavulana na wasichana. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS9_RS_UFAHAMU5_DETAIL', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS9_RS_UFAHAMU5_OPPOSITE', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS9_RS_UFAHAMU5_NOTSAID', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M9_UFH_RS_UFAHAMU5', 'KISW.G9.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Writes a summary answer that copies a whole paragraph.', '{"question":"Eleza kwa ufupi aya ya pili inahusu nini.","wrong_answer":"kunakili aya yote","correct_answer":"sentensi moja yenye wazo kuu la aya"}'::jsonb, 'Copying feels safe.', 'The question "Eleza kwa ufupi aya ya pili inahusu nini." with "kunakili aya yote" among the options.', 'Close the passage; say the main idea in one sentence; then check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA.M_KS9_SJ_MAANA', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA', 'Calls a diary a letter.', '{"question":"Shajara ni nini?","wrong_answer":"barua kwa rafiki","correct_answer":"kumbukumbu ya kila siku"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "barua kwa rafiki" next to the right answer and ask the question again in a new sentence.', 'Shajara ni kumbukumbu ya kila siku.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA.M_KS9_SJ_NAFSI', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA', 'Uses the third person.', '{"question":"Shajara huandikwa kwa nafsi ipi?","wrong_answer":"ya tatu","correct_answer":"ya kwanza"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya tatu" next to the right answer and ask the question again in a new sentence.', 'Shajara huandikwa kwa nafsi ya kwanza.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA.M_KS9_SJ_TAREHE', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA', 'Leaves out the date.', '{"question":"Kila ingizo la shajara huanza kwa nini?","wrong_answer":"jina la rafiki","correct_answer":"tarehe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jina la rafiki" next to the right answer and ask the question again in a new sentence.', 'Ingizo huanza kwa tarehe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA.M9_INS_NODATE_S_T5', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA', 'Writes a diary entry with no date or day.', '{"question":"Kila ingizo la shajara huanza na nini?","wrong_answer":"anwani ya insha","correct_answer":"tarehe na siku"}'::jsonb, 'The child writes it like an insha.', 'The question "Kila ingizo la shajara huanza na nini?" with "anwani ya insha" among the options.', 'Show a real diary page; each entry starts with the date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA.M9_INS_PERSON_S_T5', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA', 'Writes about himself in the third person (Juma aliamka...) in his own diary.', '{"question":"Shajara ya kibinafsi huandikwa kwa nafsi gani?","wrong_answer":"nafsi ya tatu: yeye","correct_answer":"nafsi ya kwanza: mimi"}'::jsonb, 'Stories in class are often in the third person.', 'The question "Shajara ya kibinafsi huandikwa kwa nafsi gani?" with "nafsi ya tatu: yeye" among the options.', 'Rewrite one entry with "mimi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA.M9_INS_TYPE_S_T5', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA', 'Mixes the kinds of diary (shajara ya kibinafsi and shajara ya kazi or ya shule).', '{"question":"Shajara inayoorodhesha mikutano ya kazi ya wiki ni ya aina gani?","wrong_answer":"ya kibinafsi","correct_answer":"ya kazi (ya kiofisi)"}'::jsonb, 'All diaries look alike.', 'The question "Shajara inayoorodhesha mikutano ya kazi ya wiki ni ya aina gani?" with "ya kibinafsi" among the options.', 'Sort entries: feelings and personal events vs appointments and tasks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA.M9_INS_LETTER_S_T5', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.KUANDIKA_SHAJARA', 'Writes the entry as a letter (Mpendwa..., Wako...).', '{"question":"Ni mwanzo upi unafaa katika shajara?","wrong_answer":"Mpendwa rafiki,","correct_answer":"Jumatatu, 12 Mei 2026. Leo nimeamka mapema..."}'::jsonb, 'Letters are the personal writing the child knows.', 'The question "Ni mwanzo upi unafaa katika shajara?" with "Mpendwa rafiki," among the options.', 'Compare a letter and a diary entry: who reads each?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA.M9_SJ_PUBLIC', 'KISW.G9.KUANDI.T5_INSHA_ZA_KIUAMILIFU.SHAJARA', 'Thinks a personal diary is written for others to read, so it leaves out feelings.', '{"question":"Shajara ya kibinafsi huandikwa kwa ajili ya nani?","wrong_answer":"kwa ajili ya mwalimu na wazazi","correct_answer":"kwa ajili ya mwandishi mwenyewe"}'::jsonb, 'Every writing task at school is read by the teacher.', 'The question "Shajara ya kibinafsi huandikwa kwa ajili ya nani?" with "kwa ajili ya mwalimu na wazazi" among the options.', 'Read a short model entry with feelings; discuss who it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI.M_KS9_NN_MAANA', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI', 'Thinks nge- shows a fact.', '{"question":"Hali ya masharti ya -nge- huonyesha nini?","wrong_answer":"ukweli uliotimia","correct_answer":"sharti lisilotimia"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ukweli uliotimia" next to the right answer and ask the question again in a new sentence.', '-nge- huonyesha sharti ambalo halikutimia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI.M_KS9_NN_NGE', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI', 'Mixes -nge- with -ngali-.', '{"question":"Ni sentensi ipi ina -nge-?","wrong_answer":"Angalijua angalikuja.","correct_answer":"Angejua angekuja."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Angalijua angalikuja." next to the right answer and ask the question again in a new sentence.', 'Angejua ina -nge-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI.M_KS9_NN_NGALI', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI', 'Mixes -ngali- with -nge-.', '{"question":"Ni sentensi ipi ina -ngali-?","wrong_answer":"Angejua angekuja.","correct_answer":"Angalijua angalikuja."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Angejua angekuja." next to the right answer and ask the question again in a new sentence.', 'Angalijua ina -ngali-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI.M9_NN_ONEVERB', 'KISW.G9.SARUFI.T5_HALI_ZA_MASHARTI.NGE_NGALI', 'Puts -nge- in one half of the sentence only (Ningekuwa na pesa, nitanunua).', '{"question":"Jaza: Ni___ (kuwa) tajiri, ni___ (jenga) shule.","wrong_answer":"Ningekuwa ... nitajenga","correct_answer":"Ningekuwa ... ningejenga"}'::jsonb, 'The second half is written as a plain future.', 'The question "Jaza: Ni___ (kuwa) tajiri, ni___ (jenga) shule." with "Ningekuwa ... nitajenga" among the options.', 'Both halves of an imagined condition take the same marker: -nge- ... -nge-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
