INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MSIMAMO.M_KS9_LS_MSIMAMO_NOTSAID', 'KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MSIMAMO', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MSIMAMO.M9_LSS_LS_MSIMAMO', 'KISW.G9.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MSIMAMO', 'Takes the speaker''s mention of a view he disagrees with for his own view.', '{"question":"Mzungumzaji alisema: \"Wengine husema simu ni hatari kwa wanafunzi, lakini mimi naona ni chombo cha kujifunzia.\" Msimamo wake ni upi?","wrong_answer":"simu ni hatari kwa wanafunzi","correct_answer":"simu ni chombo cha kujifunzia"}'::jsonb, 'The first view heard is taken as the speaker''s.', 'The question "Mzungumzaji alisema: "Wengine husema simu ni hatari kwa wanafunzi, lakini mimi naona ni chombo cha kujifunzia." Msimamo wake ni upi?" with "simu ni hatari kwa wanafunzi" among the options.', 'Listen for "lakini, mimi naona": the speaker''s own view follows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI.M_KS9_RP_SHAIRI_DETAIL', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI.M_KS9_RP_SHAIRI_OPPOSITE', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI.M_KS9_RP_SHAIRI_NOTSAID', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI.M9_RP_DHAMIRA_SWAP', 'KISW.G9.KUSOMA.T6_KUSOMA_KWA_KINA.RP_SHAIRI', 'Swaps maudhui (the issue the poem raises) and dhamira (what the poet aims at).', '{"question":"Katika shairi kuhusu usalama barabarani, \"kuwahimiza madereva kuwa waangalifu\" ni maudhui au dhamira?","wrong_answer":"maudhui","correct_answer":"dhamira"}'::jsonb, 'Both answer "what is it about?" for the child.', 'The question "Katika shairi kuhusu usalama barabarani, "kuwahimiza madereva kuwa waangalifu" ni maudhui au dhamira?" with "maudhui" among the options.', 'Maudhui: the issue (usalama barabarani). Dhamira: the aim (kuhimiza, kuonya). Sort sentences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI.M_KS9_IM_MAANA', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI', 'Thinks a proverb is a joke.', '{"question":"Methali ni nini?","wrong_answer":"kichekesho","correct_answer":"msemo wenye hekima"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kichekesho" next to the right answer and ask the question again in a new sentence.', 'Methali ni msemo wenye hekima.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI.M_KS9_IM_KAZI', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI', 'Thinks the essay retells any story.', '{"question":"Insha ya methali hufanya nini?","wrong_answer":"husimulia hadithi yoyote","correct_answer":"hufafanua maana ya methali"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "husimulia hadithi yoyote" next to the right answer and ask the question again in a new sentence.', 'Insha ya methali hufafanua maana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI.M_KS9_IM_MFANO', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI', 'Wrong meaning of a proverb.', '{"question":"Methali \"Haraka haraka haina baraka\" inafundisha nini?","wrong_answer":"Fanya kila kitu upesi","correct_answer":"Kufanya mambo kwa haraka kuna hasara"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Fanya kila kitu upesi" next to the right answer and ask the question again in a new sentence.', 'Haraka kupita kiasi huleta hasara.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI.M9_INS_METHALI_T6', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI', 'Writes an explanation of what the methali means instead of a story whose events show it.', '{"question":"Insha ya methali \"Haraka Haraka Haina Baraka\" iwe vipi?","wrong_answer":"maelezo ya maana ya methali na mifano mingi","correct_answer":"kisa ambacho matukio yake yanadhihirisha ukweli wa methali"}'::jsonb, 'The child has explained methali in Kusikiliza lessons and does it again.', 'The question "Insha ya methali "Haraka Haraka Haina Baraka" iwe vipi?" with "maelezo ya maana ya methali na mifano mingi" among the options.', 'Plan a story where the first half shows the error and the end shows the methali come true.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI.M9_INS_END_T6', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Haraka Haraka Haina Baraka\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza mengi kuhusu jambo hili."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Haraka Haraka Haina Baraka"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI.M9_INS_ORDER_T6', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Haraka Haraka Haina Baraka\"?","wrong_answer":"alichelewa zaidi, ajali ilitokea, alipuuza ishara, dereva aliharakisha","correct_answer":"dereva aliharakisha, alipuuza ishara, ajali ilitokea, alichelewa zaidi"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Haraka Haraka Haina Baraka"?" with "alichelewa zaidi, ajali ilitokea, alipuuza ishara, dereva aliharakisha" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI.M9_INS_LUGHA_T6', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.KUANDIKA_INSHA_METHALI', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Haraka Haraka Haina Baraka\"?","wrong_answer":"Gari lilianguka.","correct_answer":"Gari lilipaa kama tai juu ya kilima kabla ya kugonga ukingo."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Haraka Haraka Haina Baraka"?" with "Gari lilianguka." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI.M9_IM_HALF', 'KISW.G9.KUANDI.T6_INSHA_ZA_KUBUNI.INSHA_METHALI', 'Uses only the first half of the methali or changes its words in the title.', '{"question":"Ni anwani ipi sahihi ya insha ya methali?","wrong_answer":"Haraka Haraka","correct_answer":"Haraka Haraka Haina Baraka"}'::jsonb, 'The child shortens the methali as in speech.', 'The question "Ni anwani ipi sahihi ya insha ya methali?" with "Haraka Haraka" among the options.', 'Write the whole methali as the title, word for word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA.M_KS9_VN_NAMNA', 'KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA', 'Gives a time word for manner.', '{"question":"Ni kielezi kipi cha namna?","wrong_answer":"jana","correct_answer":"polepole"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jana" next to the right answer and ask the question again in a new sentence.', 'Polepole ni kielezi cha namna.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA.M_KS9_VN_WAKATI', 'KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA', 'Gives a manner word for time.', '{"question":"Ni kielezi kipi cha wakati?","wrong_answer":"polepole","correct_answer":"kesho"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "polepole" next to the right answer and ask the question again in a new sentence.', 'Kesho ni kielezi cha wakati.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA.M_KS9_VN_SWALI', 'KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA', 'Wrong question for the adverb.', '{"question":"Kielezi cha namna hujibu swali gani?","wrong_answer":"Lini?","correct_answer":"Vipi?"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Lini?" next to the right answer and ask the question again in a new sentence.', 'Kielezi cha namna hujibu "vipi?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA.M9_VE_ADJ_FORM', 'KISW.G9.SARUFI.T6_VIELEZI.VIE_NAMNA', 'Uses an adjective form where the adverb of manner is needed (aliendesha mzuri for vizuri, alikimbia mbaya).', '{"question":"Jaza: Dereva aliendesha ___ (-zuri).","wrong_answer":"mzuri","correct_answer":"vizuri"}'::jsonb, 'The adjective is the form learnt first.', 'The question "Jaza: Dereva aliendesha ___ (-zuri)." with "mzuri" among the options.', 'Manner of an action: vi- + stem (vizuri, vibaya), or kwa + noun (kwa uangalifu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI.M_KS9_LS_TATHMINI_DETAIL', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI.M_KS9_LS_TATHMINI_OPPOSITE', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI.M_KS9_LS_TATHMINI_NOTSAID', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI.M9_LST_LS_TATHMINI', 'KISW.G9.KUSIKI.T7_KUSIKILIZA_KWA_KUTAT.LS_TATHMINI', 'Judges the talk by whether he likes the speaker, not by its reasons.', '{"question":"Unatathmini mazungumzo. Ni kigezo kipi bora?","wrong_answer":"kama mzungumzaji ni rafiki yako","correct_answer":"kama hoja zina ushahidi na mpangilio"}'::jsonb, 'Loyalty to friends.', 'The question "Unatathmini mazungumzo. Ni kigezo kipi bora?" with "kama mzungumzaji ni rafiki yako" among the options.', 'Judge with names hidden, using a checklist of reasons and evidence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T7_.KUFUPISHA.M9_UFP_COPY_T7', 'KISW.G9.KUSOMA.T7_.KUFUPISHA', 'Copies whole sentences from the passage into the summary.', '{"question":"Ufupisho mzuri huandikwa vipi?","wrong_answer":"kunakili sentensi muhimu kutoka kifungu","correct_answer":"kwa maneno yako mwenyewe bila kupoteza maana"}'::jsonb, 'Copying feels safe; the child fears changing the meaning.', 'The question "Ufupisho mzuri huandikwa vipi?" with "kunakili sentensi muhimu kutoka kifungu" among the options.', 'Read, close the passage, write the point; then check it against the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T7_.KUFUPISHA.M9_UFP_EXAMPLE_T7', 'KISW.G9.KUSOMA.T7_.KUFUPISHA', 'Keeps the examples and illustrations in the summary.', '{"question":"Ni lipi liingie katika ufupisho?","wrong_answer":"Kwa mfano, kituo cha Upendo kiliwapa wazee hamsini chakula mwezi uliopita.","correct_answer":"Asasi za kijamii huwasaidia wazee, yatima na wagonjwa kupata huduma muhimu."}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho?" with "Kwa mfano, kituo cha Upendo kiliwapa wazee hamsini chakula mwezi uliopita." among the options.', 'Cross out every "kwa mfano" and every number that only illustrates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T7_.KUFUPISHA.M9_UFP_OPINION_T7', 'KISW.G9.KUSOMA.T7_.KUFUPISHA', 'Adds his own opinion or advice that the passage does not give.', '{"question":"Ni sentensi ipi isiingie katika ufupisho?","wrong_answer":"Asasi za kijamii huwasaidia wazee, yatima na wagonjwa kupata huduma muhimu.","correct_answer":"Mimi nadhani serikali inapaswa kufanya zaidi."}'::jsonb, 'The child wants to show he has views on the topic.', 'The question "Ni sentensi ipi isiingie katika ufupisho?" with "Asasi za kijamii huwasaidia wazee, yatima na wagonjwa kupata huduma muhimu." among the options.', 'Ask of every sentence: did the writer say this?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T7_.KUFUPISHA.M9_UFP_LENGTH_T7', 'KISW.G9.KUSOMA.T7_.KUFUPISHA', 'Goes over the word limit (80 words) or writes in notes with no sentences.', '{"question":"Umeambiwa ufupishe kwa maneno 80. Ufanye nini?","wrong_answer":"andika zaidi ili usiache kitu","correct_answer":"andika sentensi kamili zisizozidi maneno 80"}'::jsonb, 'The child is afraid of leaving out a point.', 'The question "Umeambiwa ufupishe kwa maneno 80. Ufanye nini?" with "andika zaidi ili usiache kitu" among the options.', 'Count words after the first draft; join points that repeat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA.M9_INS_HISIA_T7', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA', 'States feelings with one word (nilihuzunika) and never shows them, so the reader feels nothing.', '{"question":"Ni sentensi ipi inamgusa msomaji zaidi?","wrong_answer":"Nilihuzunika.","correct_answer":"Machozi yalinitiririka nilipoona kibanda chetu kikiteketea."}'::jsonb, 'Showing a feeling needs words for the body and the scene.', 'The question "Ni sentensi ipi inamgusa msomaji zaidi?" with "Nilihuzunika." among the options.', 'Turn "nilihuzunika" into what the body did and what was seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA.M9_INS_LUGHA_T7', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Siku Katika Kituo cha Watoto Yatima\"?","wrong_answer":"Watoto walifurahi.","correct_answer":"Macho ya Amani, yaliyojaa matumaini, yalinitazama nilipomkabidhi kitabu kipya."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Siku Katika Kituo cha Watoto Yatima"?" with "Watoto walifurahi." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA.M9_INS_MSAMIATI_T7', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Siku Katika Kituo cha Watoto Yatima\"?","wrong_answer":"Watoto walifurahi.","correct_answer":"Macho ya Amani, yaliyojaa matumaini, yalinitazama nilipomkabidhi kitabu kipya."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Siku Katika Kituo cha Watoto Yatima"?" with "Watoto walifurahi." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA.M9_INS_DETAIL_T7', 'KISW.G9.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_HISIA', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Siku Katika Kituo cha Watoto Yatima\"?","wrong_answer":"Watoto walifurahi.","correct_answer":"Macho ya Amani, yaliyojaa matumaini, yalinitazama nilipomkabidhi kitabu kipya."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Siku Katika Kituo cha Watoto Yatima"?" with "Watoto walifurahi." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI.M_KS9_VE_MAHALI', 'KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI', 'Gives a number word for place.', '{"question":"Ni kielezi kipi cha mahali?","wrong_answer":"mara mbili","correct_answer":"pale"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mara mbili" next to the right answer and ask the question again in a new sentence.', 'Pale ni kielezi cha mahali.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI.M_KS9_VE_IDADI', 'KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI', 'Gives a place word for number.', '{"question":"Ni kielezi kipi cha idadi?","wrong_answer":"huku","correct_answer":"mara mbili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "huku" next to the right answer and ask the question again in a new sentence.', 'Mara mbili ni kielezi cha idadi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI.M_KS9_VE_SWALI', 'KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI', 'Wrong question for the adverb.', '{"question":"Kielezi cha mahali hujibu swali gani?","wrong_answer":"Lini?","correct_answer":"Wapi?"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Lini?" next to the right answer and ask the question again in a new sentence.', 'Kielezi cha mahali hujibu "wapi?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI.M9_VE_MARA', 'KISW.G9.SARUFI.T7_VIELEZI.VIE_MAHALI', 'Writes the adverb of number as a number adjective (mara mbili is right; the child writes mbili mara or wawili).', '{"question":"Jaza: Alikuja ___ (2).","wrong_answer":"wawili","correct_answer":"mara mbili"}'::jsonb, 'The number adjective is better known.', 'The question "Jaza: Alikuja ___ (2)." with "wawili" among the options.', 'How many times? mara + number: mara mbili, mara tatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI.M9_ORL_NOREASONS_T8', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI', 'Tries to persuade by repeating the demand, with no reasons or benefits.', '{"question":"Unawashawishi wenzako wajiunge na klabu ya mazingira. Ni lipi bora?","wrong_answer":"Jiungeni! Jiungeni! Jiungeni!","correct_answer":"Jiungeni kwa sababu tutapanda miti, tutajifunza na tutashinda tuzo."}'::jsonb, 'Insisting feels like persuading.', 'The question "Unawashawishi wenzako wajiunge na klabu ya mazingira. Ni lipi bora?" with "Jiungeni! Jiungeni! Jiungeni!" among the options.', 'Every claim gets a reason and a benefit for the listener.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI.M9_ORL_THREAT_T8', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI', 'Uses threats or insults to persuade.', '{"question":"Ni lipi ni ushawishi unaofaa?","wrong_answer":"Msipojiunga mtaona!","correct_answer":"Mkijiunga, mtafaidika kwa njia hizi..."}'::jsonb, 'Pressure works at the playground.', 'The question "Ni lipi ni ushawishi unaofaa?" with "Msipojiunga mtaona!" among the options.', 'Compare a threat and a benefit: which keeps the friend?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI.M9_ORL_SLANG_T8', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI.M9_ORL_OFFTOPIC_T8', 'KISW.G9.KUSIKI.T8_UZUNGUMZAJI_WA_KUSHA.KUSHAWISHI', 'Answers or speaks on something other than the topic (kujiunga na klabu ya amani shuleni).', '{"question":"Mada ni kujiunga na klabu ya amani shuleni. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia kujiunga na klabu ya amani shuleni kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni kujiunga na klabu ya amani shuleni. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI.M9_FAS_PLACEONLY_T8', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI', 'Gives only the place as mandhari, and leaves out the time and the social setting.', '{"question":"Mandhari ya \"Sauti ya Mama Dunia\" ni yapi?","wrong_answer":"msitu unaokatwa","correct_answer":"msitu unaokatwa, wakati wa ukame"}'::jsonb, 'Mandhari is first taught as "mahali".', 'The question "Mandhari ya "Sauti ya Mama Dunia" ni yapi?" with "msitu unaokatwa" among the options.', 'Make three boxes: mahali, wakati, hali ya kijamii; fill each from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI.M9_FAS_PLOT_LIST_T8', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI', 'Gives a list of the characters, or a summary of the message, as the ploti.', '{"question":"Ploti ya \"Sauti ya Mama Dunia\" ni nini?","wrong_answer":"orodha ya wahusika: Mama Dunia (nafsineni) na Mkata Miti","correct_answer":"mfuatano wa matukio tangu mwanzo hadi mwisho"}'::jsonb, 'Ploti is a new word and the child grabs what he knows about the work.', 'The question "Ploti ya "Sauti ya Mama Dunia" ni nini?" with "orodha ya wahusika: Mama Dunia (nafsineni) na Mkata Miti" among the options.', 'Ploti is the chain of events with cause: because A, then B. Build it with event cards and arrows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI.M9_FAS_PLOT_ORDER_T8', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI', 'Puts the events of the ploti in the order he remembers them, not the order of the story.', '{"question":"Ni tukio lipi huja kwanza katika ploti ya \"Sauti ya Mama Dunia\"?","wrong_answer":"Mkata Miti anaangusha mti wa mwisho","correct_answer":"tukio la mwanzo kabisa la kazi"}'::jsonb, 'The climax is remembered first.', 'The question "Ni tukio lipi huja kwanza katika ploti ya "Sauti ya Mama Dunia"?" with "Mkata Miti anaangusha mti wa mwisho" among the options.', 'Number the events on the page; then check the order against the chapters or scenes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI.M9_FAS_NOUSE_T8', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MANDHARI', 'Names the mandhari but cannot say why it matters to the story (it is "just where it happened").', '{"question":"Mandhari ya msitu unaokatwa yana umuhimu gani katika \"Sauti ya Mama Dunia\"?","wrong_answer":"ni mahali tu hadithi ilipotokea","correct_answer":"yanaonyesha hali ya wahusika na kuchangia uharibifu wa mazingira"}'::jsonb, 'Setting has been taught as a fact to find, not as a tool of the author.', 'The question "Mandhari ya msitu unaokatwa yana umuhimu gani katika "Sauti ya Mama Dunia"?" with "ni mahali tu hadithi ilipotokea" among the options.', 'Ask: could the story happen the same way anywhere else? What does this place add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO.M9_FAS_UBETI_T8M', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO', 'Counts the mishororo of the whole poem as the mishororo of one ubeti.', '{"question":"Shairi lina beti 4 za mishororo 4. Kila ubeti una mishororo mingapi?","wrong_answer":"16","correct_answer":"4"}'::jsonb, 'The child counts every line on the page.', 'The question "Shairi lina beti 4 za mishororo 4. Kila ubeti una mishororo mingapi?" with "16" among the options.', 'Box each ubeti; count inside one box only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO.M9_FAS_VINA_T8M', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO', 'Looks for vina at the start of the lines, or only at the end, not in the middle (vina vya kati).', '{"question":"Vina vya kati hupatikana wapi?","wrong_answer":"mwanzoni mwa mshororo","correct_answer":"mwishoni mwa ukwapi (kipande cha kwanza)"}'::jsonb, 'English rhyme is only at the end of the line.', 'The question "Vina vya kati hupatikana wapi?" with "mwanzoni mwa mshororo" among the options.', 'Colour the last syllable of each half-line; compare down the poem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO.M9_FAS_MIZANI_T8M', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO', 'Counts words or letters, not syllables, as mizani.', '{"question":"Mizani ya mshororo \"Elimu ni ufunguo\" ni mingapi?","wrong_answer":"3","correct_answer":"8"}'::jsonb, 'Counting words is the habit from other subjects.', 'The question "Mizani ya mshororo "Elimu ni ufunguo" ni mingapi?" with "3" among the options.', 'Clap each syllable; each ends in a vowel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO.M9_FAS_KIBWAGIZO_T8M', 'KISW.G9.KUSOMA.T8_KUSOMA_KWA_KINA.SHAIRI_MUUNDO', 'Takes the kibwagizo (the line repeated in every ubeti) for an ordinary line, or does not know its use.', '{"question":"Mshororo unaorudiwa mwishoni mwa kila ubeti huitwa?","wrong_answer":"kiitikio cha wimbo tu","correct_answer":"kibwagizo (kiitikio)"}'::jsonb, 'The repeated line looks like a printing repeat.', 'The question "Mshororo unaorudiwa mwishoni mwa kila ubeti huitwa?" with "kiitikio cha wimbo tu" among the options.', 'Mark the line in each ubeti; say what it stresses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI.M_KS9_MK_MABANO', 'KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI', 'Uses a hyphen for extra information.', '{"question":"Ni alama ipi huweka maelezo ya ziada?","wrong_answer":"kistari kifupi","correct_answer":"mabano"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kistari kifupi" next to the right answer and ask the question again in a new sentence.', 'Mabano huweka maelezo ya ziada.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI.M_KS9_MK_KISTARI', 'KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI', 'Uses brackets between numbers.', '{"question":"Ni alama ipi inatumika kati ya tarakimu kama kurasa 5 hadi 10?","wrong_answer":"mabano","correct_answer":"kistari kifupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mabano" next to the right answer and ask the question again in a new sentence.', 'Kistari kifupi hutumika kati ya tarakimu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI.M_KS9_MK_NENO', 'KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI', 'Wrong use at the end of a line.', '{"question":"Ni alama ipi hutumika kuvunja neno mwishoni mwa mstari?","wrong_answer":"koloni","correct_answer":"kistari kifupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "koloni" next to the right answer and ask the question again in a new sentence.', 'Kistari kifupi huvunja neno.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI.M9_MK_DASH_HYPHEN', 'KISW.G9.KUANDI.T8_VIAKIFISHI.MABANO_KISTARI', 'Uses the kistari kifupi between words that are not joined (mama-alikuja), or leaves it out between numbers of a range (2020 2026).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Masomo ni kuanzia ukurasa 10 20.","correct_answer":"Masomo ni kuanzia ukurasa 10-20."}'::jsonb, 'The short dash is new and its uses are not fixed.', 'The question "Ni ipi imeandikwa sawa?" with "Masomo ni kuanzia ukurasa 10 20." among the options.', 'Kistari kifupi joins ranges (10-20), compound words (bata-mzinga) and a word broken at the end of a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA.M_KS9_GU_UKUTA', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA', 'Uses ya- for ukuta.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Ukuta yameanguka.","correct_answer":"Ukuta umeanguka."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Ukuta yameanguka." next to the right answer and ask the question again in a new sentence.', 'Ukuta ni wa U-ZI na hutumia u-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA.M_KS9_GU_KUTA', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA', 'Uses u- for the plural kuta.', '{"question":"Chagua sentensi sahihi kwa wingi.","wrong_answer":"Kuta umeanguka.","correct_answer":"Kuta zimeanguka."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Kuta umeanguka." next to the right answer and ask the question again in a new sentence.', 'Wingi wa U-ZI hutumia zi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA.M_KS9_GU_MAJI', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA', 'Uses zi- for maji.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Maji zimemwagika.","correct_answer":"Maji yamemwagika."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Maji zimemwagika." next to the right answer and ask the question again in a new sentence.', 'Maji ni ya YA-YA na hutumia ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA.M9_GU_UZI_PLURAL', 'KISW.G9.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_UZI_YAYA', 'Gives a U-ZI noun a ma- plural (ukuta -> makuta) as if it were U-YA.', '{"question":"Wingi wa \"ukuta\" ni?","wrong_answer":"makuta","correct_answer":"kuta"}'::jsonb, 'U-YA (ugonjwa/magonjwa) is recent and its plural rule spreads.', 'The question "Wingi wa "ukuta" ni?" with "makuta" among the options.', 'Test with known pairs: ukuta/kuta, ufunguo/funguo, uzi/nyuzi are U-ZI.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SWAP_T9', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /nj/ for /j/, so jia (to come by way of) becomes njia (a path or a way).', '{"question":"Mwalimu anasema: \"jia\". Umesikia neno lipi?","wrong_answer":"njia","correct_answer":"jia"}'::jsonb, 'The nasal (n- or m-) before j is soft and quick; a child who does not hear it writes and says the word without it, or adds it where it does not belong, and the meaning changes.', 'The question "Mwalimu anasema: "jia". Umesikia neno lipi?" with "njia" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SPELL_T9', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (njaa where jaa is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"to be full\".","wrong_answer":"njaa","correct_answer":"jaa"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "to be full"." with "njaa" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SAME_T9', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"jaa\" na \"njaa\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""jaa" na "njaa" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_TWISTER_T9', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Biashara ya mtandaoni inakua kwa kasi.","correct_answer":"Njoroge alijaa njaa njiani akanunua njugu kwa Juma."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Biashara ya mtandaoni inakua kwa kasi." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M9_MAT_SYLL_T9', 'KISW.G9.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Splits the syllable with the nasal wrongly (n-jia instead of keeping the nasal with its consonant).', '{"question":"Neno \"njia\" lina silabi zipi?","wrong_answer":"n-jia","correct_answer":"nji-a"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "njia" lina silabi zipi?" with "n-jia" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS9_RS_USHAWISHI_DETAIL', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS9_RS_USHAWISHI_OPPOSITE', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS9_RS_USHAWISHI_NOTSAID', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M9_USH_RS_USHAWISHI', 'KISW.G9.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Takes the writer''s claim for a proven fact and does not see the persuading words.', '{"question":"Katika kifungu, \"Kila mtu mwenye busara hutumia simu hii\" ni nini?","wrong_answer":"ukweli uliothibitishwa","correct_answer":"mbinu ya ushawishi"}'::jsonb, 'Strong claims look like facts.', 'The question "Katika kifungu, "Kila mtu mwenye busara hutumia simu hii" ni nini?" with "ukweli uliothibitishwa" among the options.', 'Mark words that push the reader (kila mtu, bora zaidi, usikose).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA.M9_INS_AYA_T9', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA', 'Puts several ideas in one paragraph, or one idea across many tiny paragraphs, so no idea is built up.', '{"question":"Aya nzuri ya insha \"Duka Langu la Mtandaoni\" ina nini?","wrong_answer":"mawazo mengi tofauti","correct_answer":"wazo moja kuu linalokuzwa kwa maelezo na mifano"}'::jsonb, 'Paragraphs are made where the child pauses, not where an idea ends.', 'The question "Aya nzuri ya insha "Duka Langu la Mtandaoni" ina nini?" with "mawazo mengi tofauti" among the options.', 'Topic sentence first; then two or three sentences that develop only it; a link to the next paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA.M9_INS_ORDER_T9', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Duka Langu la Mtandaoni\"?","wrong_answer":"biashara ilistawi, nilitangaza kwa busara, wateja walikuwa wachache, nilianzisha duka","correct_answer":"nilianzisha duka, wateja walikuwa wachache, nilitangaza kwa busara, biashara ilistawi"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Duka Langu la Mtandaoni"?" with "biashara ilistawi, nilitangaza kwa busara, wateja walikuwa wachache, nilianzisha duka" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA.M9_INS_MTAZAMO_T9', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA', 'Switches between "I" and "he" for the narrator, or between views, in one insha.', '{"question":"Ni lipi ni kosa katika insha moja?","wrong_answer":"kuanza \"nilikwenda...\" kisha \"alikwenda...\" kwa msimulizi yuleyule","correct_answer":"kutumia nafsi moja ya msimulizi tangu mwanzo hadi mwisho"}'::jsonb, 'The child forgets who is telling the story.', 'The question "Ni lipi ni kosa katika insha moja?" with "kuanza "nilikwenda..." kisha "alikwenda..." kwa msimulizi yuleyule" among the options.', 'Decide the narrator before writing; circle every verb of the narrator and check the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA.M9_INS_VIDOKEZO_T9', 'KISW.G9.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_WAZO_BAINA_YA_AYA', 'Plans with points (vidokezo) that do not belong to the title, or writes the insha without using the points planned.', '{"question":"Ni kidokezo kipi hakifai kwa insha \"Duka Langu la Mtandaoni\"?","wrong_answer":"Bei ya sukari imepanda dukani.","correct_answer":"nilianzisha duka"}'::jsonb, 'The child lists whatever comes to mind and does not check each point against the title.', 'The question "Ni kidokezo kipi hakifai kwa insha "Duka Langu la Mtandaoni"?" with "Bei ya sukari imepanda dukani." among the options.', 'Write the title at the top of the plan; tick each point only if it helps to tell that story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU.M_KS9_GK_KUSOMA', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU', 'Uses ki- for a verbal noun.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Kusoma kinafurahisha.","correct_answer":"Kusoma kunafurahisha."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Kusoma kinafurahisha." next to the right answer and ask the question again in a new sentence.', 'Vitenzi-jina hutumia ku-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU.M_KS9_GK_PA', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU', 'Uses ku- for a near place.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Hapa kuzuri.","correct_answer":"Hapa pazuri."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hapa kuzuri." next to the right answer and ask the question again in a new sentence.', 'Mahali karibu hutumia pa-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU.M_KS9_GK_MU', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU', 'Uses pa- for inside.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Humu pazuri.","correct_answer":"Humu mwazuri."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Humu pazuri." next to the right answer and ask the question again in a new sentence.', 'Ndani hutumia mu-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU.M9_GK_VERBAL_PLACE', 'KISW.G9.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KU_PAKUMU', 'Mixes KU of verbal nouns with KU of place (Kusoma kunapendeza / Kule kunapendeza) and gives the verbal noun place meaning.', '{"question":"\"Kuogelea kwake kulitushangaza.\" \"Ku-\" hapa ni ya nini?","wrong_answer":"mahali (PA-KU-MU)","correct_answer":"kitenzi-jina (KU)"}'::jsonb, 'The two ku- forms look the same.', 'The question ""Kuogelea kwake kulitushangaza." "Ku-" hapa ni ya nini?" with "mahali (PA-KU-MU)" among the options.', 'Ask: is it an activity (kuogelea) or a place (kule, nyumbani)?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO.M9_FSI_FORMULA_T10', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO', 'Starts or ends without the opening or closing formula (Mtani wangu!).', '{"question":"Msimulizi anaanzaje?","wrong_answer":"anaanza moja kwa moja na kisa","correct_answer":"\"Mtani wangu!\" na hadhira hujibu \"Naam mtani!\""}'::jsonb, 'Telling has been practised as reading a text aloud.', 'The question "Msimulizi anaanzaje?" with "anaanza moja kwa moja na kisa" among the options.', 'Practise the formula with the class answering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO.M9_FSI_FLAT_T10', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO', 'Presents in one flat voice, with no change for characters or feelings.', '{"question":"Unapowasilisha, sauti yako iweje?","wrong_answer":"moja tangu mwanzo hadi mwisho","correct_answer":"ibadilike kulingana na mhusika na hisia"}'::jsonb, 'The child is shy and keeps the voice safe.', 'The question "Unapowasilisha, sauti yako iweje?" with "moja tangu mwanzo hadi mwisho" among the options.', 'Give each character a voice; rehearse one line in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO.M9_FSI_GESTURE_T10', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO', 'Uses no gestures, or gestures that do not match the words.', '{"question":"Ni ishara ipi inafaa unapotaja \"mlima mrefu\"?","wrong_answer":"kushika kichwa","correct_answer":"kuinua mkono juu juu"}'::jsonb, 'The body is forgotten under the stress of remembering words.', 'The question "Ni ishara ipi inafaa unapotaja "mlima mrefu"?" with "kushika kichwa" among the options.', 'Mirror pairs: one says, one shows; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO.M9_FSI_NOAUDIENCE_T10', 'KISW.G9.KUSIKI.T10_MAZUNGUMZO.MALUMBANO', 'Presents to the floor or the teacher only, with no eye contact and no call for responses.', '{"question":"Unawasilisha mbele ya darasa. Unawaangalia nani?","wrong_answer":"chini au mwalimu peke yake","correct_answer":"hadhira yote, ukiwashirikisha"}'::jsonb, 'Reciting for marks is done to the teacher.', 'The question "Unawasilisha mbele ya darasa. Unawaangalia nani?" with "chini au mwalimu peke yake" among the options.', 'Divide the room into three; look at each part in turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA.M9_FAS_MAINMINOR_T10', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA', 'Takes a minor character who appears often for the main character.', '{"question":"Mhusika mkuu katika \"Sauti ya Mama Dunia\" ni nani?","wrong_answer":"Mkata Miti","correct_answer":"Mama Dunia (nafsineni)"}'::jsonb, 'The child counts appearances, not who the story is about.', 'The question "Mhusika mkuu katika "Sauti ya Mama Dunia" ni nani?" with "Mkata Miti" among the options.', 'Ask whose problem the story follows from start to end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA.M9_FAS_NOEVIDENCE_T10', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA', 'Gives a trait with no action from the text to show it.', '{"question":"Mama Dunia (nafsineni) ni mwenye huruma. Ni ushahidi upi unaothibitisha?","wrong_answer":"ni mwenye huruma kwa sababu ni mhusika mzuri","correct_answer":"analia akiwaomba watoto wake wasimkate"}'::jsonb, 'The child knows a trait must be named but not that it must be shown.', 'The question "Mama Dunia (nafsineni) ni mwenye huruma. Ni ushahidi upi unaothibitisha?" with "ni mwenye huruma kwa sababu ni mhusika mzuri" among the options.', 'Use the frame: trait + "kwa sababu" + an action from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA.M9_FAS_LOOKS_T10', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA', 'Gives how the character looks (mrefu, mrembo) when the character''s nature is asked.', '{"question":"Taja sifa ya kitabia ya Mama Dunia (nafsineni).","wrong_answer":"mrefu na mwembamba","correct_answer":"mwenye huruma"}'::jsonb, 'Describing people starts with appearance in lower grades.', 'The question "Taja sifa ya kitabia ya Mama Dunia (nafsineni)." with "mrefu na mwembamba" among the options.', 'Two columns: sura (looks) and tabia (character); sort the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA.M9_FAS_LESSON_T10', 'KISW.G9.KUSOMA.T10_KUSOMA_KWA_KINA.SHAIRI_WAHUSIKA', 'Takes the behaviour of a bad character as the lesson to copy.', '{"question":"Tunajifunza nini kutokana na matendo ya Mkata Miti?","wrong_answer":"tufanye kama yeye ili tufanikiwe","correct_answer":"tuepuke tabia mbaya kama zake kwa sababu zina madhara"}'::jsonb, 'The bad character often wins for a while, and the child sees the gain, not the end.', 'The question "Tunajifunza nini kutokana na matendo ya Mkata Miti?" with "tufanye kama yeye ili tufanikiwe" among the options.', 'Follow the character to the end of the work: what did his actions bring?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI.M_KS9_BK_ANWANI', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI', 'Gives one address.', '{"question":"Barua ya kuomba kazi ina anwani ngapi?","wrong_answer":"moja","correct_answer":"mbili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "moja" next to the right answer and ask the question again in a new sentence.', 'Ina anwani mbili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI.M_KS9_BK_KICHWA', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI', 'Leaves out the heading.', '{"question":"Barua ya kuomba kazi huwa na nini kabla ya ujumbe?","wrong_answer":"hakuna kitu","correct_answer":"kichwa cha barua"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "hakuna kitu" next to the right answer and ask the question again in a new sentence.', 'Ina kichwa cha barua.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI.M_KS9_BK_SIFA', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI', 'Leaves out the applicant''s qualifications.', '{"question":"Barua ya kuomba kazi hutaja nini kuhusu mwombaji?","wrong_answer":"rangi yake anayopenda","correct_answer":"sifa zake"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "rangi yake anayopenda" next to the right answer and ask the question again in a new sentence.', 'Hutaja sifa za mwombaji.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI.M9_INS_ONEADDR_T10', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI', 'Writes only one address, or puts the receiver''s address at the top right.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja, ya mwandishi","correct_answer":"mbili: ya mwandishi (kulia juu) na ya mpokeaji (kushoto)"}'::jsonb, 'The friendly letter has one address and the child carries it over.', 'The question "Barua rasmi ina anwani ngapi?" with "moja, ya mwandishi" among the options.', 'Label both addresses on a model; the child writes his own and the receiver''s on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI.M9_INS_NOREF_T10', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI', 'Leaves out the subject line (KUH: or YAH:) or writes it as a long sentence.', '{"question":"Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kazi ya muda likizoni?","wrong_answer":"Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi.","correct_answer":"KUH: OMBI LA KAZI YA MUDA LIKIZONI"}'::jsonb, 'The child does not know the reader of an official letter needs the subject before reading.', 'The question "Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kazi ya muda likizoni?" with "Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi." among the options.', 'Underline the KUH: line on three real letters; it is short and in capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI.M9_INS_CASUAL_T10', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI', 'Uses friendly words in an official letter (Mpendwa rafiki, Hujambo?, Wako akupendaye).', '{"question":"Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?","wrong_answer":"Hujambo mwalimu wangu mpendwa!","correct_answer":"Kwa Mwalimu Mkuu,"}'::jsonb, 'The friendly letter is the first letter learnt and its words come first.', 'The question "Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?" with "Hujambo mwalimu wangu mpendwa!" among the options.', 'Sort salamu and closing cards into "kirafiki" and "rasmi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI.M9_INS_SIGNOFF_T10', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_BARUA_KAZI', 'Ends with only a first name and no signature, or with "Ni mimi rafiki yako".', '{"question":"Barua rasmi humalizika vipi?","wrong_answer":"Ni mimi rafiki yako, Wanjiku","correct_answer":"Wako mtiifu, sahihi, na jina kamili: Wanjiku Kamau"}'::jsonb, 'The friendly closing is a habit.', 'The question "Barua rasmi humalizika vipi?" with "Ni mimi rafiki yako, Wanjiku" among the options.', 'Model the closing block (Wako mtiifu, sahihi, jina kamili) and have the child copy it once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI.M9_BK_NOQUAL', 'KISW.G9.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_KAZI', 'Asks for the job without saying what qualifies him (skills, education, experience) or how to reach him.', '{"question":"Ni sentensi ipi ni muhimu katika barua ya kuomba kazi?","wrong_answer":"Ninahitaji pesa sana.","correct_answer":"Nimehitimu darasa la tisa na nina ujuzi wa kutumia tarakilishi."}'::jsonb, 'The child writes about his need, not what he offers.', 'The question "Ni sentensi ipi ni muhimu katika barua ya kuomba kazi?" with "Ninahitaji pesa sana." among the options.', 'Plan: the job asked for, qualifications, why you fit, how to contact you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI.M_KS9_VH_JUU', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI', 'Gives the wrong opposite.', '{"question":"Kinyume cha juu ya ni kipi?","wrong_answer":"mbele ya","correct_answer":"chini ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mbele ya" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha juu ya ni chini ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI.M_KS9_VH_NDANI', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI', 'Gives the wrong opposite.', '{"question":"Kinyume cha ndani ya ni kipi?","wrong_answer":"juu ya","correct_answer":"nje ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "juu ya" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha ndani ya ni nje ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI.M_KS9_VH_KABLA', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI', 'Gives the wrong opposite.', '{"question":"Kinyume cha kabla ya ni kipi?","wrong_answer":"wakati wa","correct_answer":"baada ya"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wakati wa" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha kabla ya ni baada ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI.M9_VV_NEGATE', 'KISW.G9.SARUFI.T10_VINYUME_VYA_VIHUSISH.VINYUME_VIHUSISHI', 'Makes the opposite of a relating word with si (si juu ya) instead of its opposite (chini ya).', '{"question":"Kinyume cha \"ndani ya\" ni?","wrong_answer":"si ndani ya","correct_answer":"nje ya"}'::jsonb, 'Negation is a quick way to say not.', 'The question "Kinyume cha "ndani ya" ni?" with "si ndani ya" among the options.', 'Pair cards: juu ya/chini ya, ndani ya/nje ya, kabla ya/baada ya, mbele ya/nyuma ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE.M9_ORL_PROTOCOL_T11', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE', 'Skips the order of greeting the guests (itifaki) at a ceremony.', '{"question":"Unatoa hotuba katika sherehe. Unaanza vipi?","wrong_answer":"Habari zenu?","correct_answer":"Mheshimiwa mgeni rasmi, walimu, wazazi na wanafunzi wenzangu, hamjambo?"}'::jsonb, 'The child does not know the formal order.', 'The question "Unatoa hotuba katika sherehe. Unaanza vipi?" with "Habari zenu?" among the options.', 'Write the itifaki with the guests in order of rank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE.M9_ORL_WRONGMSG_T11', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE', 'Gives a message that does not fit the ceremony (sad words at a wedding).', '{"question":"Ni ujumbe upi unafaa katika sherehe ya kuhitimu?","wrong_answer":"pole kwa msiba","correct_answer":"hongera na heri katika masomo yajayo"}'::jsonb, 'The child uses the formula he knows best.', 'The question "Ni ujumbe upi unafaa katika sherehe ya kuhitimu?" with "pole kwa msiba" among the options.', 'Match ceremonies to messages on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE.M9_ORL_SLANG_T11', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE.M9_ORL_EYES_T11', 'KISW.G9.KUSIKI.T11_UZUNGUMZAJI_KATIKA_S.SHEREHE', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_COVER_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu haki za kibinadamu. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu haki za kibinadamu. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_LEVEL_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Mwanga wa Haki\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Mwanga wa Haki" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_TITLEMSG_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Mwanga wa Haki\" ni upi?","wrong_answer":"Mwanga wa Haki","correct_answer":"Kila binadamu ana haki sawa ambazo lazima ziheshimiwe."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Mwanga wa Haki" ni upi?" with "Mwanga wa Haki" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_DETAIL_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu haki za kibinadamu?","wrong_answer":"Mwandishi alizaliwa mwaka 1990.","correct_answer":"Kila binadamu ana haki sawa ambazo lazima ziheshimiwe."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu haki za kibinadamu?" with "Mwandishi alizaliwa mwaka 1990." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_KIND_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M9_MAP_WORD_T11', 'KISW.G9.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (usawa).', '{"question":"Katika matini: \"Katiba inasisitiza usawa wa watu wote mbele ya sheria.\" Neno \"usawa\" lina maana gani?","wrong_answer":"kusawazisha ardhi","correct_answer":"hali ya kuwa sawa bila ubaguzi"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Katiba inasisitiza usawa wa watu wote mbele ya sheria." Neno "usawa" lina maana gani?" with "kusawazisha ardhi" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO.M9_INS_MTAZAMO_T11', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO', 'Switches between "I" and "he" for the narrator, or between views, in one insha.', '{"question":"Ni lipi ni kosa katika insha moja?","wrong_answer":"kuanza \"nilikwenda...\" kisha \"alikwenda...\" kwa msimulizi yuleyule","correct_answer":"kutumia nafsi moja ya msimulizi tangu mwanzo hadi mwisho"}'::jsonb, 'The child forgets who is telling the story.', 'The question "Ni lipi ni kosa katika insha moja?" with "kuanza "nilikwenda..." kisha "alikwenda..." kwa msimulizi yuleyule" among the options.', 'Decide the narrator before writing; circle every verb of the narrator and check the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO.M9_INS_OFFTOPIC_T11', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Haki ya Mtoto Kusikilizwa\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwa mtazamo wangu kama mwanafunzi, mtoto akisikilizwa hujiamini na hujifunza kuwajibika."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Haki ya Mtoto Kusikilizwa", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO.M9_INS_PARAS_T11', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Haki ya Mtoto Kusikilizwa\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Haki ya Mtoto Kusikilizwa" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO.M9_INS_MSAMIATI_T11', 'KISW.G9.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MTAZAMO', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Haki ya Mtoto Kusikilizwa\"?","wrong_answer":"Haki ni nzuri.","correct_answer":"Kwa mtazamo wangu kama mwanafunzi, mtoto akisikilizwa hujiamini na hujifunza kuwajibika."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Haki ya Mtoto Kusikilizwa"?" with "Haki ni nzuri." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA.M_KS9_KN_TENDANA', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA', 'Confuses kutendana with kutendesha.', '{"question":"Ni kitenzi kipi kiko katika kauli ya kutendana?","wrong_answer":"somesha","correct_answer":"pigana"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "somesha" next to the right answer and ask the question again in a new sentence.', 'Pigana ni kutendana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA.M_KS9_KN_TENDESHA', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA', 'Confuses kutendesha with kutendana.', '{"question":"Ni kitenzi kipi kiko katika kauli ya kutendesha?","wrong_answer":"pigana","correct_answer":"somesha"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pigana" next to the right answer and ask the question again in a new sentence.', 'Somesha ni kutendesha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA.M_KS9_KN_TENDEANA', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA', 'Does not know kutendeana.', '{"question":"Ni kitenzi kipi kiko katika kauli ya kutendeana?","wrong_answer":"somesha","correct_answer":"pigiana"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "somesha" next to the right answer and ask the question again in a new sentence.', 'Pigiana ni kutendeana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA.M9_KTD_CAUSE_FORM', 'KISW.G9.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI_TENDANA', 'Forms the causative with -isha for every verb (laisha, liaisha) where the verb has its own form (laza, lisha).', '{"question":"Kutendesha kwa \"lala\" ni?","wrong_answer":"lalisha","correct_answer":"laza"}'::jsonb, 'The -isha/-esha rule is applied without exceptions.', 'The question "Kutendesha kwa "lala" ni?" with "lalisha" among the options.', 'List common irregular causatives: lala/laza, ogopa/ogofya, pona/ponya, kula/lisha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU.M_KS9_LS_UFAHAMU_DETAIL', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU.M_KS9_LS_UFAHAMU_OPPOSITE', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU.M_KS9_LS_UFAHAMU_NOTSAID', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU.M9_LSF_LS_UFAHAMU', 'KISW.G9.KUSIKI.T12_UFAHAMU_WA_KUSIKILIZ.LS_UFAHAMU', 'Answers from what he knows about the topic, not from the recording.', '{"question":"Kwa mujibu wa ulichosikiliza, kwa nini mazao yalikauka?","wrong_answer":"kwa sababu ya wadudu","correct_answer":"jibu lililotajwa katika habari"}'::jsonb, 'The topic is familiar and the child fills in.', 'The question "Kwa mujibu wa ulichosikiliza, kwa nini mazao yalikauka?" with "kwa sababu ya wadudu" among the options.', 'Ask: did the speaker say that? Point to where in your notes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_WORDBYWORD_T12', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Uvutaji wa sigara na unywaji wa pombe huharibu mapafu na ini.\"?","wrong_answer":"Uvutaji ... wa ... sigara ... na ... unywaji ... wa ... pombe ... huharibu ... mapafu ... na ... ini.","correct_answer":"Uvutaji wa sigara na unywaji wa pombe huharibu mapafu na ini."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Uvutaji wa sigara na unywaji wa pombe huharibu mapafu na ini."?" with "Uvutaji ... wa ... sigara ... na ... unywaji ... wa ... pombe ... huharibu ... mapafu ... na ... ini." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_RACE_T12', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_FLAT_T12', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, unajua madhara ya vyakula vyenye mafuta mengi?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, unajua madhara ya vyakula vyenye mafuta mengi?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_NOPAUSE_T12', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Hongera, umeacha kuvuta sigara!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Hongera, umeacha kuvuta sigara!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M9_UFS_SOUND_T12', 'KISW.G9.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (sigara read as sigala).', '{"question":"Neno \"sigara\" linatamkwa vipi?","wrong_answer":"sigala","correct_answer":"sigara"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "sigara" linatamkwa vipi?" with "sigala" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI.M_KS9_HK_LENGO', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI', 'Thinks a persuasive speech only informs.', '{"question":"Hotuba ya kushawishi hulenga nini?","wrong_answer":"kuburudisha tu","correct_answer":"kumfanya msikilizaji akubali wazo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kuburudisha tu" next to the right answer and ask the question again in a new sentence.', 'Hotuba ya kushawishi hulenga kushawishi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI.M_KS9_HK_MWANZO', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI', 'Starts with the call to action.', '{"question":"Hotuba huanza kwa nini?","wrong_answer":"wito","correct_answer":"salamu na utangulizi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "wito" next to the right answer and ask the question again in a new sentence.', 'Hotuba huanza kwa salamu na utangulizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI.M_KS9_HK_HOJA', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI', 'Leaves out reasons.', '{"question":"Hotuba ya kushawishi hutumia nini kuunga wazo?","wrong_answer":"hoja na mifano","correct_answer":"kelele tu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "hoja na mifano" next to the right answer and ask the question again in a new sentence.', 'Hutumia hoja na mifano.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI.M9_INS_ITIFAKI_T12', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI', 'Starts the speech with no greeting of the guests in order (itifaki).', '{"question":"Hotuba huanza vipi?","wrong_answer":"moja kwa moja na hoja ya kwanza","correct_answer":"kwa itifaki: Mheshimiwa mgeni rasmi, walimu, wazazi..."}'::jsonb, 'The child writes a speech like an insha.', 'The question "Hotuba huanza vipi?" with "moja kwa moja na hoja ya kwanza" among the options.', 'Model the itifaki line and the order of rank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI.M9_INS_ESSAY_T12', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI', 'Writes about the listeners in the third person instead of speaking to them (Wanafunzi wanapaswa... instead of Wanafunzi wenzangu, tunapaswa...).', '{"question":"Ni sentensi ipi inafaa katika hotuba?","wrong_answer":"Wanafunzi wanapaswa kunawa mikono.","correct_answer":"Wanafunzi wenzangu, tunapaswa kunawa mikono."}'::jsonb, 'The speech is written, so it takes the voice of an essay.', 'The question "Ni sentensi ipi inafaa katika hotuba?" with "Wanafunzi wanapaswa kunawa mikono." among the options.', 'Read the draft aloud to the class; change every "wao" to "sisi" or "nyinyi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI.M9_INS_NOTHANKS_T12', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI', 'Ends without thanking the audience or closing (Asanteni kwa kunisikiliza).', '{"question":"Hotuba humalizika vipi?","wrong_answer":"kwa hoja ya mwisho tu","correct_answer":"kwa muhtasari na \"Asanteni kwa kunisikiliza\""}'::jsonb, 'The child stops when the points run out.', 'The question "Hotuba humalizika vipi?" with "kwa hoja ya mwisho tu" among the options.', 'Model a closing: a call to act and thanks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI.M9_INS_FACTLESS_T12', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.KUANDIKA_HOTUBA_KUSHAWISHI', 'Gives an information speech with no facts the listener can use (dates, places, steps).', '{"question":"Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu tuepuke vyakula visivyo na afya?","wrong_answer":"Ugonjwa huu ni mbaya sana.","correct_answer":"Chanjo itatolewa katika zahanati ya Ruaka kuanzia Jumatatu ijayo."}'::jsonb, 'The child gives feelings, not information.', 'The question "Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu tuepuke vyakula visivyo na afya?" with "Ugonjwa huu ni mbaya sana." among the options.', 'Check the speech against nani, nini, lini, wapi, vipi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI.M9_HK_ONESIDED', 'KISW.G9.KUANDI.T12_HOTUBA_YA_KUSHAWISHI.HOTUBA_KUSHAWISHI', 'Persuades with feelings only and no facts, examples or answers to the other side.', '{"question":"Ni sentensi ipi inashawishi zaidi katika hotuba kuhusu vyakula visivyo na afya?","wrong_answer":"Vyakula hivi ni vibaya sana sana!","correct_answer":"Utafiti unaonyesha kwamba vinywaji vyenye sukari nyingi huchangia kisukari; tuchague maji."}'::jsonb, 'Strong feeling seems like strong persuasion.', 'The question "Ni sentensi ipi inashawishi zaidi katika hotuba kuhusu vyakula visivyo na afya?" with "Vyakula hivi ni vibaya sana sana!" among the options.', 'Each point: claim, fact or example, benefit to the listener.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA.M_KS9_SZ_MAANA', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA', 'Thinks a tata sentence has one meaning.', '{"question":"Sentensi tata ina nini?","wrong_answer":"maana moja tu","correct_answer":"maana zaidi ya moja"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "maana moja tu" next to the right answer and ask the question again in a new sentence.', 'Sentensi tata ina maana zaidi ya moja.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA.M_KS9_SZ_KISAHILI', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA', 'Calls a clear sentence tata.', '{"question":"Ni sentensi ipi ni tata?","wrong_answer":"Mama anapika.","correct_answer":"Mama alimpiga mtoto na fimbo."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mama anapika." next to the right answer and ask the question again in a new sentence.', 'Sentensi tata inaweza kufasiriwa kwa njia mbili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA.M_KS9_SZ_SABABU', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA', 'Does not know the cause of the ambiguity.', '{"question":"Sentensi tata hutokana na nini?","wrong_answer":"matumizi ya herufi kubwa","correct_answer":"muundo unaoleta maana mbili"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "matumizi ya herufi kubwa" next to the right answer and ask the question again in a new sentence.', 'Muundo huleta maana mbili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA.M9_ST_ONE_MEANING', 'KISW.G9.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI_TATA', 'Gives only one meaning of an ambiguous sentence (Alimpigia mpira: kicked the ball to him, or kicked the ball for him).', '{"question":"\"Mama alimpikia mtoto chakula\" ina maana ngapi?","wrong_answer":"moja","correct_answer":"mbili au zaidi: alimpikia kwa niaba yake au kumpa"}'::jsonb, 'The child reads the meaning that comes first.', 'The question ""Mama alimpikia mtoto chakula" ina maana ngapi?" with "moja" among the options.', 'Read the sentence as two different speakers would; draw each meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA.M9_FSI_MAIN_T13', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA', 'Names a character who only appears once as the main one.', '{"question":"Mhusika mkuu katika mazungumzo hii ni nani?","wrong_answer":"mhusika aliyetajwa mara moja","correct_answer":"Bibi (mwawaidhi)"}'::jsonb, 'The child picks the most striking name.', 'The question "Mhusika mkuu katika mazungumzo hii ni nani?" with "mhusika aliyetajwa mara moja" among the options.', 'Ask whom the whole text is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA.M9_FSI_NOEVID_T13', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA', 'Gives a trait with no line or action as evidence.', '{"question":"Bibi (mwawaidhi) ni mwenye hekima. Thibitisha.","wrong_answer":"kwa sababu ni mzuri","correct_answer":"anatumia methali na mifano kuwaonya wajukuu"}'::jsonb, 'Naming the trait feels like the answer.', 'The question "Bibi (mwawaidhi) ni mwenye hekima. Thibitisha." with "kwa sababu ni mzuri" among the options.', 'Frame: sifa + kwa sababu + action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA.M9_FSI_ANIMAL_T13', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA', 'Takes an animal character literally, not as standing for people (Sungura is just a hare).', '{"question":"Katika mazungumzo, Bibi (mwawaidhi) anawakilisha nini?","wrong_answer":"mnyama wa porini tu","correct_answer":"watu wenye tabia kama zake katika jamii"}'::jsonb, 'Animal characters look like animal facts.', 'The question "Katika mazungumzo, Bibi (mwawaidhi) anawakilisha nini?" with "mnyama wa porini tu" among the options.', 'Ask which people in the community behave like this character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA.M9_FSI_LESSON_T13', 'KISW.G9.KUSIKI.T13_MAZUNGUMZO.MAWAIDHA', 'Draws the wrong lesson from a character (copy the trickster because he won).', '{"question":"Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?","wrong_answer":"tuwe wajanja ili tushinde","correct_answer":"ujanja wa kudanganya huleta adhabu"}'::jsonb, 'The trick is remembered; the ending is not.', 'The question "Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?" with "tuwe wajanja ili tushinde" among the options.', 'Trace the character to the end: what did he gain and lose?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU.M9_FAS_SIMMET_T13', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU', 'Calls a comparison with kama a sitiari, or one without kama a tashbihi.', '{"question":"\"Dunia ni mama analia\" ni mbinu gani?","wrong_answer":"tashbihi","correct_answer":"tashihisi"}'::jsonb, 'Both compare; the child has not fixed which one uses kama, mithili ya or kana kwamba.', 'The question ""Dunia ni mama analia" ni mbinu gani?" with "tashbihi" among the options.', 'Circle kama, mithili ya, kana kwamba: present means tashbihi; absent means sitiari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU.M9_FAS_NAMEONLY_T13', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU', 'Names the device but cannot say what it does in the work.', '{"question":"Mbinu ya tashihisi katika \"Dunia ni mama analia\" ina umuhimu gani?","wrong_answer":"ni tashihisi","correct_answer":"inaipa dunia sifa za binadamu ili tuone uchungu wake"}'::jsonb, 'Devices have been taught as labels to find.', 'The question "Mbinu ya tashihisi katika "Dunia ni mama analia" ina umuhimu gani?" with "ni tashihisi" among the options.', 'Always add "inasaidia..." after the label: picture, feeling, stress, humour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU.M9_FAS_LITERAL_T13', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU', 'Reads a figure of speech literally.', '{"question":"\"Dunia ni mama analia\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"inaipa dunia sifa za binadamu ili tuone uchungu wake"}'::jsonb, 'The child reads the words, not the picture.', 'The question ""Dunia ni mama analia" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what does the writer want us to see?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU.M9_FAS_TAKRIRI_T13', 'KISW.G9.KUSOMA.T13_KUSOMA_KWA_KINA.SHAIRI_MBINU', 'Does not notice repetition (takriri) or rhetorical questions as devices.', '{"question":"\"Nitarudi, nitarudi, nitarudi!\" ni mbinu gani?","wrong_answer":"kosa la uchapishaji","correct_answer":"takriri: kurudia neno kusisitiza"}'::jsonb, 'Repetition looks like a mistake to a child taught not to repeat words.', 'The question ""Nitarudi, nitarudi, nitarudi!" ni mbinu gani?" with "kosa la uchapishaji" among the options.', 'Read the line aloud; what feeling does the repetition add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI.M9_INS_DETAIL_T13', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Hali ya Kijiji Baada ya Mafuriko\"?","wrong_answer":"Kijiji kilikuwa kibaya.","correct_answer":"Matope mazito yalifunika njia zote huku harufu ya mimea iliyooza ikienea kila kona."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Hali ya Kijiji Baada ya Mafuriko"?" with "Kijiji kilikuwa kibaya." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI.M9_INS_HISIA_T13', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI', 'States feelings with one word (nilihuzunika) and never shows them, so the reader feels nothing.', '{"question":"Ni sentensi ipi inamgusa msomaji zaidi?","wrong_answer":"Nilihuzunika.","correct_answer":"Machozi yalinitiririka nilipoona kibanda chetu kikiteketea."}'::jsonb, 'Showing a feeling needs words for the body and the scene.', 'The question "Ni sentensi ipi inamgusa msomaji zaidi?" with "Nilihuzunika." among the options.', 'Turn "nilihuzunika" into what the body did and what was seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI.M9_INS_LUGHA_T13', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Hali ya Kijiji Baada ya Mafuriko\"?","wrong_answer":"Kijiji kilikuwa kibaya.","correct_answer":"Matope mazito yalifunika njia zote huku harufu ya mimea iliyooza ikienea kila kona."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Hali ya Kijiji Baada ya Mafuriko"?" with "Kijiji kilikuwa kibaya." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI.M9_INS_PARAS_T13', 'KISW.G9.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_HALI', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Hali ya Kijiji Baada ya Mafuriko\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Hali ya Kijiji Baada ya Mafuriko" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI.M_KS9_UM_NGE', 'KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI', 'Wrong negation of nge.', '{"question":"Kanusha: Angekuja.","wrong_answer":"Hangekuja","correct_answer":"Asingekuja"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hangekuja" next to the right answer and ask the question again in a new sentence.', '-nge- hukanushwa kwa -singe-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI.M_KS9_UM_NGALI', 'KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI', 'Wrong negation of ngali.', '{"question":"Kanusha: Angalisoma.","wrong_answer":"Hangalisoma","correct_answer":"Asingalisoma"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hangalisoma" next to the right answer and ask the question again in a new sentence.', '-ngali- hukanushwa kwa -singali-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI.M_KS9_UM_KI', 'KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI', 'Wrong negation of ki.', '{"question":"Kanusha: Akisoma.","wrong_answer":"Hakisoma","correct_answer":"Asiposoma"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hakisoma" next to the right answer and ask the question again in a new sentence.', '-ki- hukanushwa kwa -sipo-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI.M9_UM_NGALI', 'KISW.G9.SARUFI.T13_UKANUSHAJI.UKANUSHAJI_MASHARTI', 'Negates -ngali- with ha- (hangalikuja) instead of -singali- (asingalikuja).', '{"question":"Kanusha: Angalikuja, tungalifurahi.","wrong_answer":"Hangalikuja, hatungalifurahi.","correct_answer":"Asingalikuja, tusingalifurahi."}'::jsonb, 'Ha- is the default negative.', 'The question "Kanusha: Angalikuja, tungalifurahi." with "Hangalikuja, hatungalifurahi." among the options.', 'Pattern: -nge- -> -singe-, -ngali- -> -singali-, -ki- -> -sipo-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA.M9_FSI_DEVICE_T14', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA', 'Does not see a device of language (repetition, simile, sound words) or calls it a mistake.', '{"question":"\"Haba na haba hujaza kibaba\" ni kipengele gani cha lugha?","wrong_answer":"kosa la lugha","correct_answer":"methali"}'::jsonb, 'The child has been told not to repeat words or use sounds in writing.', 'The question ""Haba na haba hujaza kibaba" ni kipengele gani cha lugha?" with "kosa la lugha" among the options.', 'Read aloud; what does the device add for the listener?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA.M9_FSI_LITERAL_T14', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA', 'Reads a figure of speech literally.', '{"question":"\"Haba na haba hujaza kibaba\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"inahimiza kulipa kodi kidogo kidogo"}'::jsonb, 'The child reads words, not pictures.', 'The question ""Haba na haba hujaza kibaba" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what is meant?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA.M9_FSI_USE_T14', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA', 'Names a device but cannot say why it matters (it makes the text nice).', '{"question":"Kipengele cha methali kina umuhimu gani?","wrong_answer":"kinapamba tu","correct_answer":"inahimiza kulipa kodi kidogo kidogo"}'::jsonb, 'Devices are taught as labels.', 'The question "Kipengele cha methali kina umuhimu gani?" with "kinapamba tu" among the options.', 'Always add what it does: picture, rhythm, memory, stress, feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA.M9_FSI_AUDIENCE_T14', 'KISW.G9.KUSIKI.T14_MAZUNGUMZO.LUGHA_MAWAIDHA', 'Does not see the call-and-response or the audience''s part as part of the language.', '{"question":"Msikilizaji anaposema \"Tega!\" au kuitikia wimbo, hiyo ni nini?","wrong_answer":"kelele zisizo na maana","correct_answer":"ushirikishaji wa hadhira, sehemu ya utungo"}'::jsonb, 'Written texts have no audience part.', 'The question "Msikilizaji anaposema "Tega!" au kuitikia wimbo, hiyo ni nini?" with "kelele zisizo na maana" among the options.', 'Perform it in class with and without the response; what is lost?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS9_RS_MJADALA_DETAIL', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS9_RS_MJADALA_OPPOSITE', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS9_RS_MJADALA_NOTSAID', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M9_MJD_RS_MJADALA', 'KISW.G9.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Gives only one side of the debate when both views are asked.', '{"question":"Kifungu kina mitazamo ipi kuhusu suala hili?","wrong_answer":"mtazamo wa upande mmoja tu","correct_answer":"mitazamo ya pande zote mbili"}'::jsonb, 'The child agrees with one side and reads only it.', 'The question "Kifungu kina mitazamo ipi kuhusu suala hili?" with "mtazamo wa upande mmoja tu" among the options.', 'Two columns: wanaounga mkono / wanaopinga; fill both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA.M9_INS_NODATE_S_T14', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA', 'Writes a diary entry with no date or day.', '{"question":"Kila ingizo la shajara huanza na nini?","wrong_answer":"anwani ya insha","correct_answer":"tarehe na siku"}'::jsonb, 'The child writes it like an insha.', 'The question "Kila ingizo la shajara huanza na nini?" with "anwani ya insha" among the options.', 'Show a real diary page; each entry starts with the date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA.M9_INS_PERSON_S_T14', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA', 'Writes about himself in the third person (Juma aliamka...) in his own diary.', '{"question":"Shajara ya kibinafsi huandikwa kwa nafsi gani?","wrong_answer":"nafsi ya tatu: yeye","correct_answer":"nafsi ya kwanza: mimi"}'::jsonb, 'Stories in class are often in the third person.', 'The question "Shajara ya kibinafsi huandikwa kwa nafsi gani?" with "nafsi ya tatu: yeye" among the options.', 'Rewrite one entry with "mimi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA.M9_INS_TYPE_S_T14', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA', 'Mixes the kinds of diary (shajara ya kibinafsi and shajara ya kazi or ya shule).', '{"question":"Shajara inayoorodhesha mikutano ya kazi ya wiki ni ya aina gani?","wrong_answer":"ya kibinafsi","correct_answer":"ya kazi (ya kiofisi)"}'::jsonb, 'All diaries look alike.', 'The question "Shajara inayoorodhesha mikutano ya kazi ya wiki ni ya aina gani?" with "ya kibinafsi" among the options.', 'Sort entries: feelings and personal events vs appointments and tasks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA.M9_INS_LETTER_S_T14', 'KISW.G9.KUANDI.T14_INSHA_ZA_KIUAMILIFU.AINA_ZA_SHAJARA', 'Writes the entry as a letter (Mpendwa..., Wako...).', '{"question":"Ni mwanzo upi unafaa katika shajara?","wrong_answer":"Mpendwa rafiki,","correct_answer":"Jumatatu, 12 Mei 2026. Leo nimeamka mapema..."}'::jsonb, 'Letters are the personal writing the child knows.', 'The question "Ni mwanzo upi unafaa katika shajara?" with "Mpendwa rafiki," among the options.', 'Compare a letter and a diary entry: who reads each?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA.M_KS9_UU_UDOGO', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA', 'Mixes udogo and ukubwa.', '{"question":"Kijiji ni nini?","wrong_answer":"mji mkubwa","correct_answer":"mji mdogo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mji mkubwa" next to the right answer and ask the question again in a new sentence.', 'Kijiji ni mji mdogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA.M_KS9_UU_UKUBWA', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA', 'Mixes ukubwa and udogo.', '{"question":"Jitu ni nini?","wrong_answer":"mtu mdogo","correct_answer":"mtu mkubwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mtu mdogo" next to the right answer and ask the question again in a new sentence.', 'Jitu ni mtu mkubwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA.M_KS9_UU_KIAMBISHI', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA', 'Wrong prefix.', '{"question":"Ni kiambishi kipi cha udogo?","wrong_answer":"ji-","correct_answer":"ki-"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ji-" next to the right answer and ask the question again in a new sentence.', 'Udogo hutumia ki-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA.M9_UU_BOTH_AGREE', 'KISW.G9.SARUFI.T14_UDOGO_NA_UKUBWA_WA_N.UDOGO_UKUBWA', 'Changes the noun to big or small but leaves the adjective and verb in the ordinary class (jibwa kubwa anabweka).', '{"question":"Jaza: Jibwa ___ (-kubwa) ___ (bweka).","wrong_answer":"mkubwa anabweka","correct_answer":"kubwa linabweka"}'::jsonb, 'The child changes the noun only.', 'The question "Jaza: Jibwa ___ (-kubwa) ___ (bweka)." with "mkubwa anabweka" among the options.', 'Big form: LI-YA chain (jibwa kubwa linabweka); small: KI-VI chain (kibwa kidogo kinabweka).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI.M9_ORL_ACCEPTALL_T15', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI', 'Accepts everything said as true, without checking the reasons or the source.', '{"question":"Mzungumzaji anasema: \"Kila mtu anajua dawa hii hutibu magonjwa yote.\" Ufanye nini?","wrong_answer":"kukubali","correct_answer":"kuuliza ushahidi na chanzo cha habari hiyo"}'::jsonb, 'Speakers who sound sure are believed.', 'The question "Mzungumzaji anasema: "Kila mtu anajua dawa hii hutibu magonjwa yote." Ufanye nini?" with "kukubali" among the options.', 'Ask three questions of every claim: nani alisema, ushahidi gani, je ni kweli kwa wote?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI.M9_ORL_BIAS_T15', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI', 'Judges the talk by the speaker (a friend is right, a stranger wrong).', '{"question":"Unatathmini mazungumzo. Unazingatia nini?","wrong_answer":"nani anazungumza","correct_answer":"hoja, ushahidi na lugha iliyotumika"}'::jsonb, 'Loyalty to friends.', 'The question "Unatathmini mazungumzo. Unazingatia nini?" with "nani anazungumza" among the options.', 'Judge two talks with names hidden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI.M9_ORL_OFFTOPIC_T15', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI', 'Answers or speaks on something other than the topic (mchango wa vijana katika kudumisha amani).', '{"question":"Mada ni mchango wa vijana katika kudumisha amani. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia mchango wa vijana katika kudumisha amani kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni mchango wa vijana katika kudumisha amani. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI.M9_ORL_INTERRUPT_T15', 'KISW.G9.KUSIKI.T15_KUSIKILIZA_KWA_KUTAT.KUTATHMINI', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS9_UF_NAKALA', 'KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Thinks a summary copies.', '{"question":"Ufupisho ni nini?","wrong_answer":"kunakili kifungu chote","correct_answer":"kutoa habari kuu kwa ufupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kunakili kifungu chote" next to the right answer and ask the question again in a new sentence.', 'Ufupisho si kunakili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS9_UF_MANENO', 'KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Copies the passage''s words.', '{"question":"Ufupisho huandikwa kwa maneno ya nani?","wrong_answer":"ya mwandishi pekee","correct_answer":"ya mfupishaji mwenyewe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya mwandishi pekee" next to the right answer and ask the question again in a new sentence.', 'Hutumia maneno ya mfupishaji.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO.M_KS9_UF_MTIRIRIKO', 'KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Changes the order.', '{"question":"Ufupisho huhifadhi nini cha habari?","wrong_answer":"hubadilisha mpangilio","correct_answer":"mtiririko wake"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "hubadilisha mpangilio" next to the right answer and ask the question again in a new sentence.', 'Huhifadhi mtiririko.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
