INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M9_UFU_RS_UFUPISHO', 'KISW.G9.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Keeps the examples and numbers in the summary and leaves out a main point.', '{"question":"Ni lipi liingie katika ufupisho wa kifungu?","wrong_answer":"mfano mmoja wa kifungu","correct_answer":"hoja kuu ya kila aya"}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho wa kifungu?" with "mfano mmoja wa kifungu" among the options.', 'Underline the main point of each paragraph; cross out examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO.M9_UFU_UFUPISHO', 'KISW.G9.KUSOMA.T15_UFUPISHO.UFUPISHO', 'Keeps the examples and numbers in the summary and leaves out a main point.', '{"question":"Ni lipi liingie katika ufupisho wa kifungu?","wrong_answer":"mfano mmoja wa kifungu","correct_answer":"hoja kuu ya kila aya"}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho wa kifungu?" with "mfano mmoja wa kifungu" among the options.', 'Underline the main point of each paragraph; cross out examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE.M9_INS_NOSUBJ_T15', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE', 'Leaves the subject box empty or writes the whole message in it.', '{"question":"Katika baruapepe, kisanduku cha \"Kichwa\" kinaandikwa nini?","wrong_answer":"ujumbe wote","correct_answer":"maneno machache yanayotaja ujumbe, kama \"Jibu: Kongamano la Maadili ya Kitaifa\""}'::jsonb, 'The child has used chat apps that have no subject line.', 'The question "Katika baruapepe, kisanduku cha "Kichwa" kinaandikwa nini?" with "ujumbe wote" among the options.', 'Show an inbox: the subject is all the reader sees before opening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE.M9_INS_ADDR_T15', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE', 'Writes a postal address and a date at the top, as in a paper letter.', '{"question":"Baruapepe huanza vipi?","wrong_answer":"S.L.P. 120, Nakuru, na tarehe juu kulia","correct_answer":"salamu kwa mpokeaji, kama \"Habari Amina,\""}'::jsonb, 'The paper letter is the model the child knows.', 'The question "Baruapepe huanza vipi?" with "S.L.P. 120, Nakuru, na tarehe juu kulia" among the options.', 'Compare a paper letter and an email; the email programme adds the address and date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE.M9_INS_TOFIELD_T15', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE', 'Puts the receiver''s name, not the email address, in the "Kwa" box.', '{"question":"Kisanduku cha \"Kwa\" kinaandikwa nini?","wrong_answer":"Amina Otieno","correct_answer":"amina.otieno@mfano.co.ke"}'::jsonb, 'The child writes the person as on an envelope.', 'The question "Kisanduku cha "Kwa" kinaandikwa nini?" with "Amina Otieno" among the options.', 'Show what an email address looks like (jina@mahali); practise reading it aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE.M9_INS_TEXTSPEAK_T15', 'KISW.G9.KUANDI.T15_KUJIBU_BARUAPEPE.KUJIBU_BARUAPEPE', 'Writes in short chat forms (sawa, poa, nkt, 2moro) and no closing.', '{"question":"Ni sentensi ipi inafaa katika baruapepe?","wrong_answer":"Poa, tutaonana 2moro.","correct_answer":"Asante. Tutaonana kesho."}'::jsonb, 'Chat habits come into the email.', 'The question "Ni sentensi ipi inafaa katika baruapepe?" with "Poa, tutaonana 2moro." among the options.', 'Rewrite one chat message as a short email with a greeting and a closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI.M9_USK_COMMAND', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI', 'Reports a command with kwamba and the command form (Alisema kwamba nenda) instead of the -e form (aliniambia niende).', '{"question":"Badilisha: Mwalimu alisema, \"Fungua dirisha.\"","wrong_answer":"Mwalimu alisema kwamba fungua dirisha.","correct_answer":"Mwalimu aliniambia nifungue dirisha."}'::jsonb, 'The child applies the statement rule (kwamba) to every kind of speech.', 'The question "Badilisha: Mwalimu alisema, "Fungua dirisha."" with "Mwalimu alisema kwamba fungua dirisha." among the options.', 'Commands become ku-ambia + the -e form: aliniambia nifungue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI.M9_USK_TENSE_BACK', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI', 'Keeps -na- in the reported speech instead of moving it back (Alisema kwamba anaumwa, reported long after).', '{"question":"Badilisha (habari ya jana): Juma alisema, \"Ninaumwa.\"","wrong_answer":"Juma alisema kwamba anaumwa.","correct_answer":"Juma alisema kwamba alikuwa akiumwa."}'::jsonb, 'The child keeps the tense of the words heard.', 'The question "Badilisha (habari ya jana): Juma alisema, "Ninaumwa."" with "Juma alisema kwamba anaumwa." among the options.', 'When reporting later, -na- becomes alikuwa akiumwa (or -li-), -ta- becomes -nge-, -me- becomes alikuwa ame-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI.M9_USK_BACK_TO_DIRECT', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI', 'Turns reported speech back into direct speech without restoring the person (Juma alisema, "Yeye atakuja.").', '{"question":"Badilisha kuwa usemi halisi: Juma alisema kwamba angekuja.","wrong_answer":"Juma alisema, \"Yeye angekuja.\"","correct_answer":"Juma alisema, \"Nitakuja.\""}'::jsonb, 'The child adds the marks and forgets the other changes go back too.', 'The question "Badilisha kuwa usemi halisi: Juma alisema kwamba angekuja." with "Juma alisema, "Yeye angekuja."" among the options.', 'Reverse every change: yeye -> mimi, -nge- -> -ta-, siku iliyofuata -> kesho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI.M9_USK_PUNCT', 'KISW.G9.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI_KANUNI', 'Puts the comma or the question mark outside the speech marks, or starts the quoted words with a small letter.', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Mama aliuliza \"umekula\"?","correct_answer":"Mama aliuliza, \"Umekula?\""}'::jsonb, 'Marks are placed where the child pauses.', 'The question "Ni ipi imeandikwa sawa?" with "Mama aliuliza "umekula"?" among the options.', 'Rule: comma before the opening mark; capital inside; the end mark inside the closing mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
